      if (c.key === 'shown') return <td key={c.key} className={cn}>{fmtNumber(v || 0)}{r.shownStage ? <span className="c360-infer" title={`${r.shownStage} from pipeline stage`}> ({r.shownStage}p)</span> : null}</td>
