    const ctl = new AbortController()
    const onAbort = () => ctl.abort()
    if (signal) { if (signal.aborted) ctl.abort(); else signal.addEventListener('abort', onAbort, { once: true }) }
    const timer = setTimeout(() => ctl.abort(), timeoutMs)
