      if (attempt < tries - 1) { await new Promise((res) => setTimeout(res, 600 * (attempt + 1))); continue }
      const msg = aborted ? 'Timed out - the data took too long to load. Try a smaller date range or Refresh.' : (e && e.message) || 'Network error.'
