  if (row.hasGoogle) chanOpts.push(['google', 'Google'])
  const [chan, setChan] = useState(row.hasMeta && row.hasGoogle ? 'blended' : (row.hasGoogle && !row.hasMeta) ? 'google' : (row.hasMeta && !row.hasGoogle) ? 'meta' : 'blended')
