function clientMovers(row, tr, win) {
  const w = (tr.windows || []).find((x) => x.n === win); if (!w) return []
  const chans = []; if (row.hasMeta) chans.push(['meta', 'Meta']); if (row.hasGoogle) chans.push(['google', 'Google'])
  const out = []
  for (const [ck, cl] of chans) {
    const d = w[ck]; if (!d || (d.spend || 0) < 1) continue
    const cpl = d.results ? d.spend / d.results : null
    const cplP = d.resultsPrev ? d.spendPrev / d.resultsPrev : null
    const cplPct = pctChg(cpl, cplP); if (cplPct == null) continue
    out.push({ c: row.c, clientId: row.id, clientName: row.name, chan: ck, channel: cl, cpl, cplP, cplPct, spend: d.spend, spendPrev: d.spendPrev, spendPct: pctChg(d.spend, d.spendPrev), results: d.results, resultsPrev: d.resultsPrev, resPct: pctChg(d.results, d.resultsPrev), booked: d.booked, bookedPrev: d.bookedPrev, win })
}
  return out
}
// Rules-based "why" from the spend vs results decomposition of a CPL move.
function moverReason(m) {
  const unit = m.chan === 'google' ? 'conversions' : 'leads'
  const p = (v) => (v == null ? '-' : `${v > 0 ? '+' : ''}${v.toFixed(0)}%`)
  const sp = m.spendPct, rp = m.resPct
  if (m.cplPct > 0) { // cost went up (worse)
    if (rp != null && rp < -5 && (sp == null || Math.abs(sp) <= 12)) return `${unit} fell ${Math.abs(rp).toFixed(0)}% on roughly steady spend`
    if (sp != null && sp > 10 && (rp == null || rp < sp)) return `spend rose ${sp.toFixed(0)}% but ${unit} only ${p(rp)}`
    if (rp != null && rp < -5 && sp != null && sp < -5) return `spend and ${unit} both fell, ${unit} faster (${p(rp)} vs ${p(sp)} spend)`
    return `${unit} ${p(rp)} vs spend ${p(sp)}`
  }
  if (rp != null && rp > 5 && (sp == null || Math.abs(sp) <= 12)) return `${unit} rose ${rp.toFixed(0)}% on roughly steady spend`
  if (sp != null && sp < -10 && (rp == null || rp > sp)) return `spend cut ${Math.abs(sp).toFixed(0)}% with ${unit} ${p(rp)}`
  return `${unit} ${p(rp)} vs spend ${p(sp)}`
}
// On-demand creative/campaign breakdown behind a mover: fetch the client's deep
// data for the last N days (which carries a prior-equal-period `prev` per entity)
// and classify what drove the cost move - scaling/new, fatiguing, pulled back, best.
function useMoverCreatives(clientId, channel, days) {
  const [st, setSt] = useState({ status: 'loading', data: null })
  useEffect(() => {
    let alive = true; setSt({ status: 'loading', data: null })
    const dayAgo = (n) => { const d = new Date(); d.setHours(12, 0, 0, 0); d.setDate(d.getDate() - n); return iso(d) }
    const to = dayAgo(1), from = dayAgo(days)
    fetch(`/.netlify/functions/windsor?client=${clientId}&channel=${channel}&from=${from}&to=${to}`)
      .then((r) => r.json()).then((j) => { if (alive) setSt({ status: j && !j.error ? 'ok' : 'err', data: j }) })
      .catch(() => { if (alive) setSt({ status: 'err', data: null }) })
    return () => { alive = false }
  }, [clientId, channel, days])
  return st
}
function moverCreativeBreakdown(j, channel) {
  const ads = (channel === 'meta' ? (j && j.meta && j.meta.ads) : (j && j.google && j.google.campaigns)) || []
  const items = ads.map((a) => {
    const res = a.results != null ? a.results : (a.leads != null ? a.leads : (a.conversions || 0))
    const spend = a.spend || 0; const pv = a.prev || {}
    const pres = pv.results != null ? pv.results : (pv.leads != null ? pv.leads : (pv.conversions || 0))
    const pspend = pv.spend || 0
    return { name: a.name, spend, res, cpl: res ? spend / res : null, pspend, pres, pcpl: pres ? pspend / pres : null }
  }).filter((x) => x.name && (x.spend > 0 || x.pspend > 0))
  return {
    scaling: items.filter((x) => x.pspend < Math.max(5, x.spend * 0.15) && x.spend >= 10).sort((a, b) => b.spend - a.spend).slice(0, 3),
    fatigue: items.filter((x) => x.pspend > 0 && x.spend > 0 && x.cpl != null && x.pcpl != null && x.cpl > x.pcpl * 1.2).sort((a, b) => (b.cpl - b.pcpl) * b.spend - (a.cpl - a.pcpl) * a.spend).slice(0, 3),
    dropped: items.filter((x) => x.pspend >= 10 && x.spend < x.pspend * 0.3).sort((a, b) => b.pspend - a.pspend).slice(0, 2),
    best: items.filter((x) => x.res > 0 && x.cpl != null && x.spend >= 5).sort((a, b) => a.cpl - b.cpl).slice(0, 2),
  }
}
function MoverDrill({ clientId, channel, days, money }) {
  const st = useMoverCreatives(clientId, channel, days)
  if (st.status === 'loading') return <div className="mov-drill"><Spinner label="Loading creative breakdown…" /></div>
  if (st.status === 'err' || !st.data) return <div className="mov-drill"><span className="cap">Couldn’t load the creative breakdown for this window.</span></div>
  const b = moverCreativeBreakdown(st.data, channel)
  const noun = channel === 'meta' ? 'creatives' : 'campaigns'
  const row = (label, arr, fmt) => arr.length ? <div className="mov-drill-row"><span className="mov-drill-lab">{label}</span><div className="mov-drill-items">{arr.map((x, i) => <div className="mov-drill-item" key={i}>{fmt(x)}</div>)}</div></div> : null
  if (!b.scaling.length && !b.fatigue.length && !b.dropped.length && !b.best.length) return <div className="mov-drill"><span className="cap">No standout {noun} - the move looks broad across the account.</span></div>
  return <div className="mov-drill">
    {row('🔥 Fatiguing (cost rising)', b.fatigue, (x) => <><b>{x.name}</b> · {money(x.pcpl)} → {money(x.cpl)} / result · {money(x.spend)} spend</>)}
    {row('🚀 Scaling / new', b.scaling, (x) => <><b>{x.name}</b> · {money(x.spend)} spend{x.cpl != null ? ` · ${money(x.cpl)} / result` : ''}</>)}
    {row('📉 Pulled back', b.dropped, (x) => <><b>{x.name}</b> · {money(x.pspend)} → {money(x.spend)} spend</>)}
    {row('⭐ Best right now', b.best, (x) => <><b>{x.name}</b> · {money(x.cpl)} / result · {money(x.spend)} spend</>)}
  </div>
}
// DOM id for a client's trend tile (per-pipeline tiles append the pipeline id) so a
// mover can scroll straight to the card it's describing.
const trCardId = (clientId, pipeId) => `tr-card-${clientId}${pipeId ? '--' + pipeId : ''}`
function MoversPanel({ list, clients, currency, onPick }) {
  const [open, setOpen] = useState(null)
  const [win, setWin] = useState(7)
  const money = (v) => fmtCurrency(v, currency)
  // Build movers per pipeline for multi-pipeline clients, so each insight says which
  // pipeline it's for (e.g. "Nexia Health Care · ADHD …") and can scroll to that exact
  // tile; single-pipeline clients stay account-level.
  const allMovers = []
  for (const r of list) {
    const t = clients[r.id]
    if (t && t.pipelines && t.pipelines.length > 1) {
      for (const p of t.pipelines) {
        if (p.unlinked || !dpPipeOn(r.id, p.id)) continue
        const prow = { ...r, name: `${r.name} · ${p.name}`, hasMeta: !!p.hasMeta, hasGoogle: !!p.hasGoogle }
        for (const m of clientMovers(prow, p, win)) allMovers.push({ ...m, scrollId: trCardId(r.id, p.id) })
      }
    } else {
      for (const m of clientMovers(r, t, win)) allMovers.push({ ...m, scrollId: trCardId(r.id) })
    }
  }
  const movers = allMovers.filter((m) => Math.abs(m.cplPct) >= 8).sort((a, b) => Math.abs(b.cplPct) - Math.abs(a.cplPct)).slice(0, 8)
  const scrollToCard = (id) => {
    const el = id && document.getElementById(id)
    if (!el) return
    el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    el.classList.add('tr-flash'); setTimeout(() => el.classList.remove('tr-flash'), 1600)
  }
  return (
    <div className="card mov-panel">
      <div className="mov-head">
        <b>📊 Biggest movers</b>
        <div className="chan-toggle sm">{MOVER_WINS.map((n) => <button key={n} className={win === n ? 'on' : ''} onClick={() => { setWin(n); setOpen(null) }}>{n}d</button>)}</div>
        <span className="cap">cost per result vs the prior {win} days · biggest changes across all clients · click a mover for its creative breakdown</span>
      </div>
      {movers.length === 0 ? <p className="cap" style={{ margin: 0 }}>Nothing moved more than 8% over the last {win} days.</p>
        : <div className="mov-list">{movers.map((m, i) => (
          <div className={`mov-item2${open === i ? ' open' : ''}`} key={i}>
            <div className="mov-item-h">
              <button className="mov-exp" onClick={() => setOpen(open === i ? null : i)} title="Creative breakdown">
                <span className={`mov-badge ${m.cplPct > 0 ? 'bad' : 'good'}`}>{m.cplPct > 0 ? '▲' : '▼'} {Math.abs(m.cplPct).toFixed(0)}%</span>
                <span className="mov-txt"><b>{m.clientName}</b> · {m.channel} cost / {m.chan === 'google' ? 'conv.' : 'lead'} {money(m.cplP)} → {money(m.cpl)}<span className="mov-why">{moverReason(m)} · {open === i ? '▾' : '▸'} creatives</span></span>
              </button>
              <button className="mov-open" onClick={() => scrollToCard(m.scrollId)} title="Scroll to this client's tile">↓</button>
            </div>
            {open === i ? <MoverDrill clientId={m.clientId} channel={m.chan} days={win} money={money} /> : null}
          </div>
        ))}</div>}
    </div>
  )
}
/* ============ Agency overview: biggest movers (paid + CRM) ============ */
// A second movers panel, on the Overview rather than Trends, and answering a
// wider question than "what happened to cost per lead". It reads the same
// cached agency trends feed, which carries 56 days of daily arrays per client -
// so every "vs the prior window" figure here is a second sum over memory we
// already hold, not another request.
//
// Basis: everything CRM-side is CREATED-date cohorted. A win counts in the
// window its LEAD was created in, not the window it was won in. Over three days
// almost no cohort has had time to close, so won / revenue / avg deal / win rate
// are only offered from 14 days up (MATURE_WIN) rather than shown as noise.
const AGY_MOVER_WINS = [3, 7, 14, 21, 28]
const MATURE_WIN = 14
const AGY_LENSES = [['all', 'All'], ['paid', 'Paid'], ['crm', 'CRM']]
// Which day a deal counts on. Closed is the default because it is the only one a
// rolling window can read as throughput: on a created basis the newest window's
// cohort has not finished closing, so every recent window reads low for
// everything downstream of the lead, and no amount of flooring fixes that.
// Created still earns its place - it is the honest basis for conversion rate,
// because it compares wins against the very leads they came from.
const AGY_BASES = [['closed', 'Closed'], ['created', 'Created']]
// Ad spend is split Meta / Google; CRM outcomes are split by the lead's source.
// "Paid" means Meta + Google together, and deliberately excludes non-paid leads -
// dividing ad spend by organic bookings would flatter every cost-per figure.
const PAID_CHANS = [['meta', 'Meta'], ['google', 'Google'], ['paid', 'Paid']]

const mergeReachMaps = (...maps) => { const o = {}; for (const m of maps) for (const k in (m || {})) o[k] = (o[k] || 0) + m[k]; return o }
// Channel slice of a {all, meta, google, other} bundle. 'paid' = Meta + Google.
const chanN = (bun, ch) => { if (!bun) return 0; if (ch === 'paid') return (bun.meta || 0) + (bun.google || 0); return bun[ch] || 0 }
const chanReach = (R, ch) => { if (!R) return {}; if (ch === 'paid') return mergeReachMaps(R.meta, R.google); return R[ch] || {} }
const safeDiv = (a, b) => (b > 0 ? a / b : null)

// Rank: percentage change alone is useless here - a client going 1 -> 3 bookings
// is +200% and would bury one going 180 -> 140. Weighting by the square root of
// the volume behind the move makes moves comparable across metrics and units,
// and the hard floors below stop anything thin qualifying in the first place.
const moverScore = (pct, vol, volPrev) => Math.abs(pct) * Math.sqrt(Math.max(1, Math.min(vol, volPrev)))
const pp = (v) => (v == null ? '–' : `${v > 0 ? '+' : ''}${v.toFixed(0)}%`)
// Why a ratio moved, decomposed into its two sides. Always true, and short
// enough to sit on one line; the two "roughly flat" cases are the ones worth
// naming because they say which side to go and look at.
function ratioWhy(numLabel, numPct, denLabel, denPct) {
  const flat = (v) => v != null && Math.abs(v) <= 8
  if (flat(numPct) && denPct != null) return `${denLabel} ${pp(denPct)} on roughly flat ${numLabel}`
  if (flat(denPct) && numPct != null) return `${numLabel} ${pp(numPct)} on roughly flat ${denLabel}`
  return `${numLabel} ${pp(numPct)} vs ${denLabel} ${pp(denPct)}`
}

// Build every candidate mover for one subject (a client, or one pipeline of a
// multi-pipeline client) in one window. Each candidate declares the volume
// behind it so the ranking can compare a cost move against a count move.
function subjectMovers(s, win, fmt, basis) {
  const w = s.w, crm = w.crm, out = []
  const money = fmt.money, int = fmt.int
  // Closed basis counts a deal on the day it was won or lost; created basis counts
  // it against the window its lead arrived in. Closed is only available where the
  // CRM app is connected - the Windsor fallback carries no status-change date - so
  // a client without it contributes no deal-level movers on this basis rather than
  // silently falling back to the other one and mislabelling itself.
  const closedOn = basis === 'closed' && !!(crm && crm.closed)
  const cohortOff = crm && (basis === 'closed' ? !crm.closed : win < MATURE_WIN)
  const mature = !cohortOff
  const WON = crm ? (closedOn ? crm.wonClosed : crm.won) : null
  const WONP = crm ? (closedOn ? crm.wonClosedPrev : crm.wonPrev) : null
  const LOST = crm ? (closedOn ? crm.lostClosed : crm.lost) : null
  const LOSTP = crm ? (closedOn ? crm.lostClosedPrev : crm.lostPrev) : null
  const REV = crm ? (closedOn ? crm.revenueClosed : crm.revenue) : null
  const REVP = crm ? (closedOn ? crm.revenueClosedPrev : crm.revenuePrev) : null
  const RSN = crm ? (closedOn ? crm.reasonsClosed : crm.reasons) : null
  const RSNP = crm ? (closedOn ? crm.reasonsClosedPrev : crm.reasonsPrev) : null
  const add = (o) => {
    const pct = pctChg(o.cur, o.prev)
    if (pct == null || !isFinite(pct)) return
    if (Math.abs(pct) < (o.minPct || 10)) return
    out.push({ ...o, pct, score: moverScore(pct, o.vol, o.volPrev), subject: s, win })
  }
  // ---- Paid: spend, results and cost per result, per channel ----
  const paidOf = (ch) => {
    if (ch === 'paid') {
      const m = w.meta || {}, g = w.google || {}
      return { spend: (m.spend || 0) + (g.spend || 0), spendPrev: (m.spendPrev || 0) + (g.spendPrev || 0), results: (m.results || 0) + (g.results || 0), resultsPrev: (m.resultsPrev || 0) + (g.resultsPrev || 0), booked: (m.booked || 0) + (g.booked || 0), bookedPrev: (m.bookedPrev || 0) + (g.bookedPrev || 0) }
    }
    return w[ch] || {}
  }
  for (const [ch, chLabel] of PAID_CHANS) {
    if (ch === 'meta' && !s.hasMeta) continue
    if (ch === 'google' && !s.hasGoogle) continue
    if (ch === 'paid' && !(s.hasMeta && s.hasGoogle)) continue   // same as one channel otherwise
    const d = paidOf(ch); if (!d.spend && !d.spendPrev) continue
    const spendPct = pctChg(d.spend, d.spendPrev), resPct = pctChg(d.results, d.resultsPrev)
    const scope = chLabel
    const cpr = safeDiv(d.spend, d.results), cprP = safeDiv(d.spendPrev, d.resultsPrev)
    if (d.spendPrev >= 200 && d.results >= 5 && d.resultsPrev >= 5) {
      add({ lens: 'paid', id: `cpr:${ch}`, metric: 'Cost per result', scope, cur: cpr, prev: cprP, vol: d.results, volPrev: d.resultsPrev, good: 'down', fmt: money, minPct: 8,
        why: ratioWhy('spend', spendPct, 'results', resPct) })
    }
    if (d.resultsPrev >= 10) {
      add({ lens: 'paid', id: `res:${ch}`, metric: 'Results', scope, cur: d.results, prev: d.resultsPrev, vol: d.results, volPrev: d.resultsPrev, good: 'up', fmt: int, minPct: 10,
        why: ratioWhy('spend', spendPct, 'cost per result', pctChg(cpr, cprP)) })
    }
    if (d.spendPrev >= 300) {
      add({ lens: 'paid', id: `spend:${ch}`, metric: 'Spend', scope, cur: d.spend, prev: d.spendPrev, vol: Math.max(1, d.results), volPrev: Math.max(1, d.resultsPrev), good: null, fmt: money, minPct: 20,
        why: `results ${pp(resPct)} · cost per result ${pp(pctChg(cpr, cprP))}` })
    }
    if (!crm) continue
    // Cost per booking is only sound at account level: a pipeline tile carries the
    // pipeline's total bookings against every channel, so a per-channel divide there
    // would charge Meta for Google's bookings too.
    if (!s.pipeId && d.bookedPrev >= 5 && d.booked >= 5 && d.spendPrev >= 200) {
      add({ lens: 'paid', id: `cpb:${ch}`, metric: 'Cost per booking', scope, cur: safeDiv(d.spend, d.booked), prev: safeDiv(d.spendPrev, d.bookedPrev), vol: d.booked, volPrev: d.bookedPrev, good: 'down', fmt: money, minPct: 10,
        why: ratioWhy('spend', spendPct, 'bookings', pctChg(d.booked, d.bookedPrev)) })
    }
    const won = chanN(WON, ch), wonP = chanN(WONP, ch)
    if (!cohortOff && won >= 3 && wonP >= 3 && d.spendPrev >= 200) {
      add({ lens: 'paid', id: `cpw:${ch}`, metric: 'Cost per won', scope, cur: safeDiv(d.spend, won), prev: safeDiv(d.spendPrev, wonP), vol: won, volPrev: wonP, good: 'down', fmt: money, minPct: 10, mature: !closedOn,
        why: ratioWhy('spend', spendPct, 'deals won', pctChg(won, wonP)) })
      const rev = chanN(REV, ch), revP = chanN(REVP, ch)
      if (d.spendPrev >= 300 && (rev > 0 || revP > 0)) {
        add({ lens: 'paid', id: `roas:${ch}`, metric: 'ROAS', scope, cur: safeDiv(rev, d.spend), prev: safeDiv(revP, d.spendPrev), vol: won, volPrev: wonP, good: 'up', fmt: fmt.mult, minPct: 10, mature: !closedOn,
          why: ratioWhy('revenue', pctChg(rev, revP), 'spend', spendPct) })
      }
    }
    // Cost per key event - one per event this client has configured, which is where
    // cost per booked / shown / consult lands without hard-coding anyone's funnel.
    for (const k of s.keRows) {
      const c = k.byChan[ch], p = k.byChanPrev[ch]
      if (!(c >= 5 && p >= 5 && d.spendPrev >= 200)) continue
      add({ lens: 'paid', id: `cpk:${ch}:${k.label}`, metric: `Cost per ${k.label.toLowerCase()}`, scope, cur: safeDiv(d.spend, c), prev: safeDiv(d.spendPrev, p), vol: c, volPrev: p, good: 'down', fmt: money, minPct: 10,
        why: ratioWhy('spend', spendPct, k.label.toLowerCase(), pctChg(c, p)) })
    }
  }
  // ---- CRM: the funnel itself, all lead sources ----
  if (crm) {
    const leads = chanN(crm.leads, 'all'), leadsP = chanN(crm.leadsPrev, 'all')
    const leadsPct = pctChg(leads, leadsP)
    const booked = (w.blended || {}).booked || 0, bookedP = (w.blended || {}).bookedPrev || 0
    const won = chanN(WON, 'all'), wonP = chanN(WONP, 'all')
    const lost = chanN(LOST, 'all'), lostP = chanN(LOSTP, 'all')
    const rev = chanN(REV, 'all'), revP = chanN(REVP, 'all')
    if (leadsP >= 10) {
      add({ lens: 'crm', id: 'leads', metric: 'Leads', scope: 'CRM', cur: leads, prev: leadsP, vol: leads, volPrev: leadsP, good: 'up', fmt: int, minPct: 10,
        why: `Meta ${int(chanN(crm.leadsPrev, 'meta'))}→${int(chanN(crm.leads, 'meta'))} · Google ${int(chanN(crm.leadsPrev, 'google'))}→${int(chanN(crm.leads, 'google'))} · other ${int(chanN(crm.leadsPrev, 'other'))}→${int(chanN(crm.leads, 'other'))}` })
    }
    if (bookedP >= 5) {
      add({ lens: 'crm', id: 'booked', metric: 'Bookings', scope: 'CRM', cur: booked, prev: bookedP, vol: booked, volPrev: bookedP, good: 'up', fmt: int, minPct: 10,
        why: ratioWhy('leads', leadsPct, 'booking rate', pctChg(safeDiv(booked, leads), safeDiv(bookedP, leadsP))) })
    }
    // A rate and its count are two ways of saying one thing when lead volume held
    // steady - "bookings 180 -> 140" and "booking rate 26% -> 20%" would take two
    // slots to report one fact. Keep the count then, and only surface the rate when
    // leads genuinely moved, which is when volume and quality have come apart.
    const leadsFlat = leadsPct != null && Math.abs(leadsPct) <= 8
    if (!leadsFlat && leadsP >= 20 && leads >= 20 && bookedP >= 5 && booked >= 5) {
      add({ lens: 'crm', id: 'bookRate', metric: 'Booking rate', scope: 'CRM', cur: safeDiv(booked, leads) * 100, prev: safeDiv(bookedP, leadsP) * 100, vol: leads, volPrev: leadsP, good: 'up', fmt: fmt.pct, minPct: 10,
        why: ratioWhy('bookings', pctChg(booked, bookedP), 'leads', leadsPct) })
    }
    for (const k of s.keRows) {
      const c = k.byChan.all, p = k.byChanPrev.all
      if (!(p >= 5)) continue
      add({ lens: 'crm', id: `ke:${k.label}`, metric: k.label, scope: 'CRM', cur: c, prev: p, vol: c, volPrev: p, good: 'up', fmt: int, minPct: 10,
        why: ratioWhy('leads', leadsPct, `${k.label.toLowerCase()} rate`, pctChg(safeDiv(c, leads), safeDiv(p, leadsP))) })
    }
    if (!cohortOff) {
      // Both windows need real volume either way. On a created basis a current
      // window of zero is indistinguishable from a cohort that simply hasn't
      // closed yet, so "deals won -100%" would be reported for almost every
      // client, almost always wrongly. A fall from 20 to 3 still reports.
      const chip = !closedOn
      const wonWhy = closedOn
        ? `${int(lost)} lost in the same window (was ${int(lostP)})`
        : ratioWhy('leads', leadsPct, 'win rate', pctChg(safeDiv(won, leads), safeDiv(wonP, leadsP)))
      if (wonP >= 3 && won >= 3) {
        add({ lens: 'crm', id: 'won', metric: 'Deals won', scope: 'CRM', cur: won, prev: wonP, vol: won, volPrev: wonP, good: 'up', fmt: int, minPct: 15, mature: chip, why: wonWhy })
      }
      if (lostP >= 3 && lost >= 3) {
        // "Deals lost went up" is a fact you can do nothing with; which reason
        // went up is one you can act on. So when a single reason accounts for
        // most of the move it becomes the mover and the total drops into the
        // why-line. When the rise is spread across reasons, the total is the
        // honest story and the biggest contributor is named beside it.
        const rTot = lost - lostP
        let top = null
        for (const nm of new Set([...Object.keys(RSN || {}), ...Object.keys(RSNP || {})])) {
          const c = (RSN && RSN[nm]) || 0, p = (RSNP && RSNP[nm]) || 0
          if (!top || Math.abs(c - p) > Math.abs(top.cur - top.prev)) top = { name: nm, cur: c, prev: p }
        }
        const dominant = top && rTot !== 0 && (top.cur - top.prev) / rTot >= 0.5 && top.prev >= 3 && top.cur >= 3
        if (dominant) {
          add({ lens: 'crm', id: `lostr:${top.name}`, metric: `Lost \u2013 ${top.name}`, scope: 'CRM', cur: top.cur, prev: top.prev, vol: top.cur, volPrev: top.prev, good: 'down', fmt: int, minPct: 15, mature: chip,
            why: `${int(Math.abs(top.cur - top.prev))} of the ${int(Math.abs(rTot))} extra losses \u00b7 ${int(lost)} lost in total (was ${int(lostP)})` })
        } else {
          add({ lens: 'crm', id: 'lost', metric: 'Deals lost', scope: 'CRM', cur: lost, prev: lostP, vol: lost, volPrev: lostP, good: 'down', fmt: int, minPct: 15, mature: chip,
            why: top && top.cur ? `spread across reasons \u00b7 biggest is ${top.name} (${int(top.prev)} \u2192 ${int(top.cur)}) \u00b7 against ${int(won)} won` : `against ${int(won)} won (was ${int(wonP)})` })
        }
      }
      if (wonP >= 3 && won >= 3 && revP > 0) {
        add({ lens: 'crm', id: 'revenue', metric: 'Revenue', scope: 'CRM', cur: rev, prev: revP, vol: won, volPrev: wonP, good: 'up', fmt: money, minPct: 15, mature: chip,
          why: `${int(won)} deals at ${money(safeDiv(rev, won))} avg (was ${int(wonP)} at ${money(safeDiv(revP, wonP))})` })
        add({ lens: 'crm', id: 'avgDeal', metric: 'Avg deal size', scope: 'CRM', cur: safeDiv(rev, won), prev: safeDiv(revP, wonP), vol: won, volPrev: wonP, good: 'up', fmt: money, minPct: 10, mature: chip,
          why: ratioWhy('revenue', pctChg(rev, revP), 'deals won', pctChg(won, wonP)) })
      }
      // Win rate is a CREATED-basis measure only. Wins closed this week against
      // leads created this week are two different cohorts, and the ratio of them
      // means nothing - it is throughput over intake, not a conversion rate.
      if (!closedOn && !leadsFlat && leadsP >= 20 && leads >= 20 && wonP >= 3 && won >= 3) {
        add({ lens: 'crm', id: 'winRate', metric: 'Win rate', scope: 'CRM', cur: safeDiv(won, leads) * 100, prev: safeDiv(wonP, leadsP) * 100, vol: leads, volPrev: leadsP, good: 'up', fmt: fmt.pct, minPct: 10, mature: true,
          why: ratioWhy('deals won', pctChg(won, wonP), 'leads', leadsPct) })
      }
    }
  }
  return out
}
// One subject per client, plus one per pipeline for multi-pipeline clients, so a
// mover can say which pipeline it belongs to instead of averaging them together.
// Key events are resolved per channel against the window's stage-reach map with
// the same engine the funnels use, so each client's own configured events drive
// the metrics rather than a hard-coded booked/shown/won ladder.
function moverSubjects(rows, clients, win) {
  const KE_CH = ['all', 'meta', 'google', 'paid']
  const subs = []
  const mk = (r, t, w, pipeId, pipeName) => {
    if (!w) return null
    const crm = w.crm
    const sp = new Map(Object.entries(t.stagePos || {}))
    const keList = keyEventsForPipe(loadKeyEvents(r.id), pipeId || 'all')
    const keRows = []
    if (crm) {
      const byLabel = new Map()
      for (const ch of KE_CH) {
        const run = (which, wonBun) => {
          const rmap = { m: new Map(Object.entries(chanReach(crm[which], ch))), total: chanN(crm[which === 'reach' ? 'leads' : 'leadsPrev'], ch) }
          return keyEventRows(keList, rmap, new Map(), sp, chanN(wonBun, ch)).filter((k) => k.kind !== 'lead' && k.kind !== 'won')
        }
        for (const k of run('reach', crm.won)) {
          let e = byLabel.get(k.label); if (!e) { e = { label: k.label, byChan: {}, byChanPrev: {} }; byLabel.set(k.label, e) }
          e.byChan[ch] = k.count
        }
        for (const k of run('reachPrev', crm.wonPrev)) {
          let e = byLabel.get(k.label); if (!e) { e = { label: k.label, byChan: {}, byChanPrev: {} }; byLabel.set(k.label, e) }
          e.byChanPrev[ch] = k.count
        }
      }
      for (const e of byLabel.values()) { for (const ch of KE_CH) { e.byChan[ch] = e.byChan[ch] || 0; e.byChanPrev[ch] = e.byChanPrev[ch] || 0 } keRows.push(e) }
    }
    return { key: `${r.id}${pipeId ? '--' + pipeId : ''}`, clientId: r.id, c: r.c, pipeId: pipeId || null,
      name: pipeName ? `${r.name} · ${pipeName}` : r.name, w, keRows,
      hasMeta: pipeId ? !!(w.meta && (w.meta.spend > 0 || w.meta.spendPrev > 0)) : !!r.hasMeta,
      hasGoogle: pipeId ? !!(w.google && (w.google.spend > 0 || w.google.spendPrev > 0)) : !!r.hasGoogle,
      utm: !!(w.crm && w.crm.utm) }
  }
  for (const r of rows) {
    const t = clients[r.id]; if (!t) continue
    const pick = (ws) => (ws || []).find((x) => x.n === win)
    if (t.pipelines && t.pipelines.length > 1) {
      for (const p of t.pipelines) {
        if (p.unlinked) continue
        const s = mk(r, t, pick(p.windows), p.id, p.name); if (s) subs.push(s)
      }
    } else {
      const s = mk(r, t, pick(t.windows), null, null); if (s) subs.push(s)
    }
  }
  return subs
}
// Funnel behind a mover: the same window's leads -> configured key events -> won,
// current vs prior, for the channel the mover is about. Costs nothing extra - it
// is the data the mover was computed from, shown a level down.
function MoverFunnel({ m, fmt, basis }) {
  const s = m.subject, crm = s.w.crm
  if (!crm) return <div className="mov-drill"><span className="cap">No CRM connected for this client, so there's no funnel behind this move.</span></div>
  const ch = m.id.includes(':') && /^(cpr|res|spend|cpb|cpw|roas|cpk):/.test(m.id) ? m.id.split(':')[1] : 'all'
  const steps = [{ label: 'Leads', cur: chanN(crm.leads, ch), prev: chanN(crm.leadsPrev, ch) }]
  for (const k of s.keRows) steps.push({ label: k.label, cur: k.byChan[ch], prev: k.byChanPrev[ch] })
  // On a closed basis the Won row counts deals closed in the window, which are
  // mostly not the leads above it - so it is labelled as its own thing and the
  // "% of leads" column is withheld rather than inviting a false conversion read.
  const closedOn = basis === 'closed' && crm.closed
  steps.push({ label: closedOn ? 'Won (closed in window)' : 'Won', cur: chanN(closedOn ? crm.wonClosed : crm.won, ch), prev: chanN(closedOn ? crm.wonClosedPrev : crm.wonPrev, ch), noRate: closedOn })
  const chLabel = ch === 'all' ? 'all lead sources' : (PAID_CHANS.find(([k]) => k === ch) || [, ch])[1]
  return (
    <div className="mov-drill">
      <div className="agy-fn-head"><span className="mov-drill-lab">Funnel · {chLabel} · last {m.win}d vs prior {m.win}d</span>
        {!s.utm ? <span className="agy-chip warn" title="This client's CRM app isn't connected, so the channel split falls back to matching the lead-source text rather than real UTMs.">source-matched split</span> : null}</div>
      <div className="agy-fn">{steps.map((st, i) => {
        const pct = pctChg(st.cur, st.prev)
        const rate = i > 0 && steps[0].cur && !st.noRate ? (st.cur / steps[0].cur) * 100 : null
        return (
          <div className="agy-fn-step" key={i}>
            <span className="agy-fn-lab">{st.label}</span>
            <span className="agy-fn-val">{fmt.int(st.prev)} → <b>{fmt.int(st.cur)}</b></span>
            <span className={`agy-fn-pct ${pct == null ? '' : pct > 0 ? 'good' : pct < 0 ? 'bad' : ''}`}>{pct == null ? '–' : pp(pct)}</span>
            <span className="agy-fn-rate">{rate == null ? '' : `${rate.toFixed(0)}% of leads`}</span>
          </div>
        )
      })}</div>
    </div>
  )
}

function AgencyMovers({ rows, currency, nonce, onPick }) {
  const tr = useTrends(nonce)
  const [win, setWin] = useState(7)
  const [lens, setLens] = useState('all')
  const [basis, setBasis] = useState('closed')
  const [open, setOpen] = useState(null)
  const fmt = useMemo(() => ({
    money: (v) => (v == null ? '–' : fmtCurrency(v, currency)),
    int: (v) => (v == null ? '–' : fmtNumber(Math.round(v))),
    pct: (v) => (v == null ? '–' : `${v.toFixed(1)}%`),
    mult: (v) => (v == null ? '–' : `${v.toFixed(2)}×`),
  }), [currency])
  // Key events come from settings, which hydrate on their own schedule - often
  // after the trends feed has already resolved. Without a settings tick in the
  // memo deps below, the panel computes once with no key events configured and
  // every cost-per-key-event and key-event-count mover silently never appears.
  const [setTick, bumpTick] = React.useReducer((x) => x + 1, 0)
  useEffect(() => onSettings(bumpTick), [])
  const clients = (tr.data && tr.data.clients) || null
  const movers = useMemo(() => {
    if (!clients) return []
    const all = []
    for (const s of moverSubjects(rows, clients, win)) all.push(...subjectMovers(s, win, fmt, basis))
    // Cap each client at its three biggest moves. This is meant to be a read across
    // the whole book - without a cap, one account having a bad fortnight takes every
    // slot and hides the other fourteen clients entirely.
    const per = new Map(), keep = []
    for (const m of all.filter((m) => lens === 'all' || m.lens === lens).sort((a, b) => b.score - a.score)) {
      const n = per.get(m.subject.key) || 0
      if (n >= 3) continue
      per.set(m.subject.key, n + 1); keep.push(m)
      if (keep.length >= 10) break
    }
    return keep
  }, [clients, rows, win, lens, basis, fmt, setTick])
  const setWinSafe = (n) => { setWin(n); setOpen(null) }
  const setLensSafe = (l) => { setLens(l); setOpen(null) }
  const setBasisSafe = (b) => { setBasis(b); setOpen(null) }
  const immature = basis === 'created' && win < MATURE_WIN
  // Closed dates come from the CRM API, which we use for every client that has a
  // location linked - there is no per-client opt-in. So a client missing them is
  // one of exactly two things, and only one of them is a problem:
  //   - no CRM location linked at all: nothing to report, nothing to fix, and
  //     nothing worth telling anyone about here;
  //   - a linked client whose read FAILED (timeout / rate limit / token), which
  //     silently fell back to the Windsor feed and is worth surfacing.
  // Counting the two together, as this note first did, made a working setup look
  // broken and hid the reads that genuinely failed.
  const gaps = useMemo(() => {
    if (!clients || basis !== 'closed') return null
    const failed = []
    for (const r of rows) {
      const t = clients[r.id]
      if (!t || !t.hasCrm) continue
      const w = (t.windows || []).find((x) => x.n === win)
      if (w && w.crm && !w.crm.closed) failed.push({ name: r.name, err: t.crmErr })
    }
    return failed
  }, [clients, rows, win, basis])
  const crmDown = tr.data && tr.data.crmConnected === false
  const head = (
    <div className="mov-head agy-mov-head">
      <b>📊 Biggest movers</b>
      <div className="chan-toggle sm">{AGY_MOVER_WINS.map((n) => <button key={n} className={win === n ? 'on' : ''} onClick={() => setWinSafe(n)}>{n}d</button>)}</div>
      <div className="chan-toggle sm">{AGY_LENSES.map(([k, l]) => <button key={k} className={lens === k ? 'on' : ''} onClick={() => setLensSafe(k)}>{l}</button>)}</div>
      <div className="chan-toggle sm" title="Closed: a deal counts on the day it was won. Created: it counts against the window its lead arrived in.">{AGY_BASES.map(([k, l]) => <button key={k} className={basis === k ? 'on' : ''} onClick={() => setBasisSafe(k)}>{l}</button>)}</div>
      <span className="cap">last {win} days vs the prior {win} · deals counted on the day they {basis === 'closed' ? 'closed' : 'came in as a lead'} · ranked by how much moved, not just the percentage · click one for the funnel behind it</span>
    </div>
  )
  if (tr.status === 'loading') return <div className="card mov-panel">{head}<Spinner label="Loading movers…" /></div>
  if (tr.status === 'err' || !clients) return <div className="card mov-panel">{head}<p className="cap" style={{ margin: 0 }}>Couldn&rsquo;t load the trends feed movers are built from - try Refresh.</p></div>
  return (
    <div className="card mov-panel">
      {head}
      {immature && lens !== 'paid' ? (
        <div className="agy-basis">
          <span className="agy-chip">Created-in-period</span>
          Won, revenue, avg deal and win rate count against the window the <b>lead</b> was created in, so they need {MATURE_WIN} days up to mean anything. Switch to <b>Closed</b> to count deals on the day they were won instead.
        </div>
      ) : crmDown && lens !== 'paid' ? (
        <div className="agy-basis">
          <span className="agy-chip warn">CRM disconnected</span>
          The Caalano Systems connection is down, so no client has close dates right now and this basis has nothing to show. Reconnect it in Settings; <b>Created</b> still works from the blended feed meanwhile.
        </div>
      ) : gaps && gaps.length && lens !== 'paid' ? (
        <div className="agy-basis">
          <span className="agy-chip warn">{gaps.length} CRM read{gaps.length === 1 ? '' : 's'} failed</span>
          <b title={gaps.map((g) => `${g.name}${g.err ? ` - ${g.err}` : ''}`).join('\n')}>{gaps.map((g) => g.name).join(', ')}</b>
          {' '}fell back to the blended feed, which carries no close date, so {gaps.length === 1 ? 'it contributes' : 'they contribute'} no deal-level movers here. Usually a timeout - hit Refresh. Their leads and bookings still count.
        </div>
      ) : null}
      {movers.length === 0 ? <p className="cap" style={{ margin: 0 }}>Nothing moved enough to report over the last {win} days{lens === 'all' ? '' : ` in ${lens === 'paid' ? 'paid' : 'CRM'}`}. Thin accounts are held back deliberately - a jump from 2 to 5 isn&rsquo;t a trend.</p>
        : <div className="mov-list agy-mov-list">{movers.map((m, i) => {
          const dir = m.good == null ? 'neu' : ((m.pct > 0) === (m.good === 'up') ? 'good' : 'bad')
          return (
            <div className={`mov-item2${open === i ? ' open' : ''}`} key={m.subject.key + m.id}>
              <div className="mov-item-h">
                <button className="mov-exp" onClick={() => setOpen(open === i ? null : i)} title="Show the funnel behind this move">
                  <span className={`mov-badge ${dir}`}>{m.pct > 0 ? '▲' : '▼'} {Math.abs(m.pct).toFixed(0)}%</span>
                  <span className="mov-txt">
                    <b>{m.subject.name}</b> <span className={`agy-scope sc-${String(m.scope).toLowerCase()}`}>{m.scope}</span> · {m.metric} {m.fmt(m.prev)} → {m.fmt(m.cur)}
                    {m.mature ? <span className="agy-chip tiny" title="Counted against the window the lead was created in, not when the deal closed - the most recent window is still maturing, so this reads low.">cohort</span> : null}
                    <span className="mov-why">{m.why} · {open === i ? '▾' : '▸'} funnel</span>
                  </span>
                </button>
                <button className="mov-open" onClick={() => onPick(m.subject.c)} title="Open this client">→</button>
              </div>
              {open === i ? <>
                <MoverFunnel m={m} fmt={fmt} basis={basis} />
                {/^(cpr|spend|res):(meta|google)$/.test(m.id) ? <MoverDrill clientId={m.subject.clientId} channel={m.id.split(':')[1]} days={m.win} money={fmt.money} /> : null}
              </> : null}
            </div>
          )
        })}</div>}
    </div>
  )
}
function TrendsTab({ rows, currency, nonce, onPick }) {
  const tr = useTrends(nonce)
  if (tr.status === 'loading') return <div className="tr-list"><TrendsLoadBar status={tr.status} partial={tr.partial} retry={tr.retry} of={tr.of} /><div className="card"><Spinner label={tr.retry ? `Meta results were slow - retrying (${tr.retry}/${tr.of})…` : 'Loading performance trends…'} /></div></div>
  if (tr.status === 'err' || !tr.data || !tr.data.clients) return <div className="tr-list"><TrendsLoadBar status={tr.status} partial={tr.partial} retry={tr.retry} of={tr.of} /><div className="card"><p className="cap" style={{ margin: 0 }}>Couldn't load trends - try Refresh.</p></div></div>
  const clients = tr.data.clients
  // Respect the per-client Daily Performance visibility toggles (Settings → Daily
  // performance). Hidden clients drop out entirely; hidden pipelines drop their tile.
  const list = rows.filter((r) => clients[r.id] && (r.hasMeta || r.hasGoogle) && dpClientOn(r.id))
    .slice().sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }))
  // Order a client's pipeline tiles alphabetically, keeping "Unlinked campaigns" last.
  const pipeOrder = (pipes) => pipes.slice().sort((a, b) => (a.unlinked ? 1 : 0) - (b.unlinked ? 1 : 0) || String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }))
  return (
    <div className="tr-list">
      <TrendsLoadBar status={tr.status} partial={tr.partial} retry={tr.retry} of={tr.of} />
      {list.length > 0 && <MoversPanel list={list} clients={clients} currency={currency} onPick={onPick} />}
      {list.flatMap((r) => {
        const t = clients[r.id]
        // Multi-pipeline clients render one full tile per pipeline (each a complete,
        // channel-split card), instead of one combined card with sub-tables. Hidden
        // pipelines (unchecked in Settings) are dropped; unlinked-spend tile is kept.
        if (t.pipelines && t.pipelines.length > 1) {
          const vis = pipeOrder(t.pipelines).filter((p) => p.unlinked || dpPipeOn(r.id, p.id))
          return vis.map((p) => {
            const prow = { ...r, name: `${r.name} · ${p.name}`, hasMeta: !!p.hasMeta, hasGoogle: !!p.hasGoogle }
            return <ClientTrend key={`${r.id}:${p.id}`} row={prow} tr={p} currency={currency} onPick={onPick} domId={trCardId(r.id, p.id)} clientId={r.id} pipeId={p.unlinked ? '_unlinked' : p.id} stagePos={t.stagePos} />
          })
        }
        return [<ClientTrend key={r.id} row={r} tr={t} currency={currency} onPick={onPick} domId={trCardId(r.id)} clientId={r.id} pipeId="all" stagePos={t.stagePos} />]
      })}
      {!list.length && <div className="card"><p className="cap" style={{ margin: 0 }}>No client trend data available for the last 8 weeks.</p></div>}
      <Caveat>Each window compares the last N days to the previous N days. Green = cost fell (better), red = cost rose. Booked calls come from Caalano Systems pipeline stages; where UTM attribution is connected they're split by first-touch channel, so Meta / Google cost-per-booked uses that channel's own bookings. Otherwise the toggle divides that channel's spend by total booked calls.</Caveat>
    </div>
  )
}

/* ============ Weekly Traffic Light ============ */
// AI insights (Weekly Traffic Light briefings) persist per client on the SERVER
// like every other setting - see the SETTINGS store below - so a briefing one
// person generates is shared across the team and devices. (Read/written via the
// shared SETTINGS cache; the functions live here for locality with the tab.)
const AI_KEY = 'caalano_ai_insights'
export function loadInsights(clientId) { return (SETTINGS.insights && SETTINGS.insights[clientId]) || null }
export function saveInsights(clientId, v) { SETTINGS.insights = { ...(SETTINGS.insights || {}), [clientId]: v }; writeLS(AI_KEY, SETTINGS.insights); saveSettingsRemote({ insights: { [clientId]: v } }); bumpSettings() }
// Minimal markdown renderer (bold, headings, bullets) for the AI briefing.
export function MdText({ text }) {
  const bold = (s) => s.split(/(\*\*[^*]+\*\*)/g).map((p, i) => (p.startsWith('**') && p.endsWith('**') ? <strong key={i}>{p.slice(2, -2)}</strong> : p))
  return <div className="ai-md">{String(text || '').split('\n').map((ln, i) => {
    const t = ln.trim()
    if (!t) return null
    if (t.startsWith('### ')) return <h5 key={i}>{bold(t.slice(4))}</h5>
    if (t.startsWith('## ')) return <h4 key={i}>{bold(t.slice(3))}</h4>
    if (t.startsWith('# ')) return <h4 key={i}>{bold(t.slice(2))}</h4>
    if (/^[-*•]\s/.test(t)) return <div className="ai-li" key={i}>• {bold(t.replace(/^[-*•]\s/, ''))}</div>
    if (/^\d+\.\s/.test(t)) return <div className="ai-li ai-num" key={i}>{bold(t)}</div>
    return <p key={i}>{bold(t)}</p>
  })}</div>
}
function useWeekly(clientId, weeks, nonce = 0, wonBasis = 'closed') {
  const [state, setState] = useState({ status: 'loading', data: null })
  useEffect(() => {
    if (!clientId) return
    let alive = true; setState({ status: 'loading', data: null })
    fetch(`/.netlify/functions/windsor?scope=weekly&client=${clientId}&weeks=${weeks}&wonBasis=${wonBasis}${nonce ? `&_r=${nonce}` : ''}`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error('http'))))
      .then((j) => { if (alive) setState({ status: j && j.weeks ? 'ok' : 'err', data: j }) })
      .catch(() => { if (alive) setState({ status: 'err', data: null }) })
    return () => { alive = false }
  }, [clientId, weeks, nonce, wonBasis])
  return state
}
function WkTile({ label, value, num, target, goodWhenDown = true }) {
  const has = target != null && target !== '' && Number(target) > 0 && num != null && isFinite(num)
  const pct = has ? ((num - Number(target)) / Number(target)) * 100 : null
  const dir = pct == null ? 'flat' : (goodWhenDown ? (pct <= 0 ? 'up' : 'down') : (pct >= 0 ? 'up' : 'down'))
  return <div className="wk-tile"><div className="wk-lab">{label}</div><div className="wk-val">{value}</div>{pct != null ? <div className={`wk-d ${dir}`}>{pct > 0 ? '▲' : pct < 0 ? '▼' : '■'} {Math.abs(pct).toFixed(1)}% vs KPI</div> : <div className="wk-d flat">no KPI set</div>}</div>
}
// volume bars (right axis) + cost-$ line (left axis) + optional KPI line ($ left)
function WkDual({ data, costKey, costName, countKey, countName, kpi, currency, costColor, countColor }) {
  return (
    <ResponsiveContainer width="100%" height={240}>
      <ComposedChart data={data} margin={{ left: -4, right: 6, top: 10 }}>
        <CartesianGrid stroke="var(--border)" vertical={false} />
        <XAxis dataKey="label" fontSize={11} stroke="var(--muted)" />
        <YAxis yAxisId="l" fontSize={10} stroke="var(--muted)" tickFormatter={(v) => '$' + fmtCompact(v)} />
        <YAxis yAxisId="r" orientation="right" fontSize={10} stroke="var(--muted)" allowDecimals={false} />
        <Tooltip formatter={(v, n) => (n === countName ? fmtNumber(v) : fmtCurrency(v, currency))} />
        <Legend />
        <Bar yAxisId="r" dataKey={countKey} name={countName} fill={countColor || '#bcd0ff'} radius={[3, 3, 0, 0]} maxBarSize={42}>
          <LabelList dataKey={countKey} position="insideTop" fill="var(--text)" fontSize={10} fontWeight={700} formatter={(v) => (v ? fmtNumber(v) : '')} />
        </Bar>
        <Line yAxisId="l" type="monotone" dataKey={costKey} name={costName} stroke={costColor || '#4f7cff'} strokeWidth={2.5} dot={{ r: 3 }} />
        {kpi != null && kpi > 0 && <ReferenceLine yAxisId="l" y={kpi} stroke="var(--text)" strokeDasharray="5 4" label={{ value: `KPI ${fmtCurrency(kpi, currency)}`, fontSize: 10, fill: 'var(--muted)', position: 'insideTopRight' }} />}
      </ComposedChart>
    </ResponsiveContainer>
  )
}
// ---------------------------------------------------------------------------
// Funnel Forecaster - what a month of spend should turn into, stage by stage.
//
// Two ways in. A CLIENT forecast reads the client's own numbers: the last 30
// days of paid spend per channel (what a lead costs today) and the last 90 days
// of CRM outcomes for a pipeline (how far paid leads get, per channel). Move the
// spend and the funnel re-forecasts. A SCENARIO is the same model with every
// number typed by hand - spend, cost per lead, the stages, and the step
// conversion between each - for a client that does not exist yet, or a funnel
// that does not exist yet.
//
// Everything is an average applied forward. That is the honest limit of it: a
// forecast here is "if next month behaves like the last three", never a promise,
// and the page says so. It is staff-only for exactly that reason.
// ---------------------------------------------------------------------------
const FC_CHANNELS = [["meta", "Meta", "#4f7cff"], ["google", "Google", "#12b886"], ["other", "Non-paid", "#9aa5b4"]]
const FC_MIN_CHANNEL_LEADS = 15   // below this a channel's own stage rates are noise; blended rates are used
const FC_MIN_CPL_LEADS = 10       // below this the 30-day CPL is replaced by the 90-day one

// The model, from a client's ccdrill payloads. `d90` carries the funnel and the
// channel split; `d30` carries the current run-rate of spend and paid leads.
function fcModelFromClient(d90, d30, pipeId, kpis) {
  if (!d90 || !d90.pipelinesFunnel) return null
  const pipe = (d90.pipelinesFunnel || []).find((p) => p.id === pipeId) || d90.pipelinesFunnel[0]
  if (!pipe) return null
  const contrib = ((d90.pipeContribution || []).find((p) => p.id === pipe.id)) || null
  const chan = (contrib && contrib.chan) || { meta: {}, google: {}, other: {} }
  const leads = { meta: chan.meta.leads || 0, google: chan.google.leads || 0, other: chan.other.leads || 0 }
  const won = { meta: chan.meta.won || 0, google: chan.google.won || 0, other: chan.other.won || 0 }
  const totalLeads = leads.meta + leads.google + leads.other
  const stages = (pipe.stages || []).slice().sort((a, b) => a.pos - b.pos)
  // Cumulative reach per channel: the share of that channel's leads that got at
  // least this far. Thin channels borrow the blended curve.
  const rates = {}
  for (const c of ['meta', 'google', 'other']) {
    const own = leads[c] >= FC_MIN_CHANNEL_LEADS
    rates[c] = stages.map((s) => (own ? (s[c] || 0) / leads[c] : (totalLeads ? (s.count || 0) / totalLeads : 0)))
  }
  const winRate = {}
  for (const c of ['meta', 'google', 'other']) winRate[c] = leads[c] >= FC_MIN_CHANNEL_LEADS ? won[c] / leads[c] : (totalLeads ? (won.meta + won.google + won.other) / totalLeads : 0)
  // Cost per lead: today's rate if it rests on enough leads, else the quarter's.
  const sp30 = (d30 && d30.spend) || {}, pd30 = (d30 && d30.paid) || {}
  const sp90 = d90.spend || {}, pd90 = d90.paid || {}
  const cplOf = (c) => {
    const l30 = pd30[`${c}Leads`] || 0, l90 = pd90[`${c}Leads`] || 0
    if (l30 >= FC_MIN_CPL_LEADS && sp30[c] > 0) return { cpl: sp30[c] / l30, basis: '30d' }
    if (l90 > 0 && sp90[c] > 0) return { cpl: sp90[c] / l90, basis: '90d' }
    return { cpl: null, basis: null }
  }
  const meta = cplOf('meta'), google = cplOf('google')
  // A client with several pipelines spends on all of them at once; this
  // pipeline's starting spend is its share of the account's last 30 days, by its
  // share of last month's leads - the same split the KPI targets and the Channel
  // split use. Cost per lead stays account-level: a Meta lead costs what it
  // costs whichever pipeline it lands in.
  const c30 = (d30 && d30.pipeContribution) || []
  const pl = (x) => (x && x.chan ? (x.chan.meta.leads || 0) + (x.chan.google.leads || 0) + (x.chan.other.leads || 0) : 0)
  const mine30 = c30.find((x) => x.id === pipe.id), all30 = c30.reduce((n, x) => n + pl(x), 0)
  const share = c30.length > 1 && all30 ? pl(mine30) / all30 : 1
  const rev = (contrib && contrib.revenue) || 0, wonAll = won.meta + won.google + won.other
  const avgDeal = kpis && Number(kpis.clientLtv) > 0 ? Number(kpis.clientLtv) : (wonAll ? rev / wonAll : 0)
  return {
    pipeId: pipe.id, pipeName: pipe.name,
    stages: stages.map((s) => ({ key: s.id, name: s.name })),
    channels: {
      meta: { cpl: meta.cpl, cplBasis: meta.basis, rates: rates.meta, winRate: winRate.meta, own: leads.meta >= FC_MIN_CHANNEL_LEADS },
      google: { cpl: google.cpl, cplBasis: google.basis, rates: rates.google, winRate: winRate.google, own: leads.google >= FC_MIN_CHANNEL_LEADS },
    },
    other: { leadsPerMonth: leads.other / 3, rates: rates.other, winRate: winRate.other },
    baseSpend: { meta: (sp30.meta || 0) * share, google: (sp30.google || 0) * share },
    spendShare: share,
    avgDeal, avgDealBasis: kpis && Number(kpis.clientLtv) > 0 ? 'LTV target' : 'won deals, last 90d',
    sample: { leads, won, days: 90 },
  }
}

// The arithmetic. Pure, so it can be tested and so a scenario and a client
// forecast are the same thing with different inputs.
//   model  as above (a scenario supplies the same shape by hand)
//   spend  { meta, google } per month
//   opts   { cplRise: 0..1 - how much CPL rises per +50% spend over baseline;
//            includeOther: keep the non-paid baseline in the totals }
function fcForecast(model, spend, opts = {}) {
  const rise = Number(opts.cplRise) || 0
  const out = { leads: { meta: 0, google: 0, other: 0 }, cpl: {}, spend: { meta: 0, google: 0, total: 0 } }
  for (const c of ['meta', 'google']) {
    const ch = model.channels[c]
    const s = Math.max(0, Number(spend[c]) || 0)
    out.spend[c] = s; out.spend.total += s
    if (!ch || !ch.cpl || !s) { out.leads[c] = 0; out.cpl[c] = ch ? ch.cpl : null; continue }
    // Past the current run-rate, each extra half-again of spend lifts CPL by
    // `rise`. Below it, CPL holds - nobody gets cheaper leads by spending less.
    const base = model.baseSpend && model.baseSpend[c] > 0 ? model.baseSpend[c] : s
    const over = Math.max(0, s / base - 1)
    const cpl = ch.cpl * (1 + rise * (over / 0.5))
    out.cpl[c] = cpl
    out.leads[c] = s / cpl
  }
  out.leads.other = opts.includeOther === false ? 0 : (model.other ? model.other.leadsPerMonth || 0 : 0)
  out.leads.total = out.leads.meta + out.leads.google + out.leads.other
  const reach = (c, i) => { const r = c === 'other' ? model.other && model.other.rates : model.channels[c] && model.channels[c].rates; return out.leads[c] * ((r && r[i]) || 0) }
  let prev = out.leads.total
  out.stages = model.stages.map((s, i) => {
    const m = reach('meta', i), g = reach('google', i), o = reach('other', i)
    const total = m + g + o
    const row = { key: s.key, name: s.name, meta: m, google: g, other: o, total, ofLeads: out.leads.total ? total / out.leads.total : 0, step: prev ? total / prev : 0, costEach: total ? out.spend.total / total : null }
    prev = total
    return row
  })
  // Won. A client model carries a measured win rate per channel (won / leads in
  // the sample). A scenario has no such thing - its last stage IS the win, so
  // won is whatever reached it. One switch, so the two never disagree.
  const last = out.stages[out.stages.length - 1]
  if (model.wonIsLastStage && last) out.won = { meta: last.meta, google: last.google, other: last.other }
  else {
    const wr = (c) => (c === 'other' ? (model.other && model.other.winRate) || 0 : (model.channels[c] && model.channels[c].winRate) || 0)
    out.won = { meta: out.leads.meta * wr('meta'), google: out.leads.google * wr('google'), other: out.leads.other * wr('other') }
  }
  out.won.total = out.won.meta + out.won.google + out.won.other
  const deal = model.avgDeal || 0
  out.revenue = out.won.total * deal
  const paidWon = out.won.meta + out.won.google
  out.cac = paidWon ? out.spend.total / paidWon : null
  out.paidCpl = out.leads.meta + out.leads.google ? out.spend.total / (out.leads.meta + out.leads.google) : null
  out.roas = out.spend.total ? (paidWon * deal) / out.spend.total : null
  // Unit economics, when the inputs exist. Every figure says what it is made of,
  // because "margin" means three different things to three different people:
  //   gross profit     revenue x gross margin
  //   LTV              a typed lifetime value, else the deal x purchases per customer
  //   LTV:CAC          lifetime revenue per customer against what one cost to win
  //   LTV-GP:CAC       the same on gross profit - the one that says whether the
  //                    business actually keeps anything
  //   net of ad spend  revenue - spend  (what the user asked for as "gross margin")
  //   contribution     gross profit - spend  (what is left after goods AND ads)
  const margin = model.grossMargin != null && model.grossMargin !== '' ? Math.max(0, Math.min(1, Number(model.grossMargin) / 100)) : null
  const purchases = Number(model.purchases) > 0 ? Number(model.purchases) : 1
  const ltv = Number(model.ltv) > 0 ? Number(model.ltv) : deal * purchases
  out.econ = {
    margin, purchases, ltv,
    grossProfit: margin != null ? out.revenue * margin : null,
    ltvCac: out.cac ? ltv / out.cac : null,
    ltvGpCac: out.cac && margin != null ? (ltv * margin) / out.cac : null,
    netOfSpend: out.revenue - out.spend.total,
    contribution: margin != null ? out.revenue * margin - out.spend.total : null,
    perCustomer: { revenue: deal, grossProfit: margin != null ? deal * margin : null, cac: out.cac, contribution: margin != null && out.cac != null ? deal * margin - out.cac : null },
  }
  return out
}

// A scenario is typed as STEP conversions (each stage as a share of the one
// before), because that is how people think about a funnel. The model wants
// cumulative reach, so this converts.
function fcStepsToRates(steps) { let acc = 1; return steps.map((p) => { acc *= Math.max(0, Math.min(1, (Number(p) || 0) / 100)); return acc }) }
function fcRatesToSteps(rates) { let prev = 1; return rates.map((r) => { const s = prev ? (r / prev) * 100 : 0; prev = r; return Math.round(s * 10) / 10 }) }
function fcModelFromScenario(sc) {
  const stages = (sc.stages || []).map((s, i) => ({ key: `s${i}`, name: s.name || `Stage ${i + 1}` }))
  const rates = fcStepsToRates((sc.stages || []).map((s) => s.step))
  // The last stage is the win, so the win rate is simply how many get there.
  const winRate = rates.length ? rates[rates.length - 1] : 0
  const ch = (c) => ({ cpl: Number(sc[`${c}Cpl`]) > 0 ? Number(sc[`${c}Cpl`]) : null, cplBasis: 'typed', rates, winRate, own: true })
  return {
    pipeId: 'scenario', pipeName: sc.name || 'Scenario',
    stages, channels: { meta: ch('meta'), google: ch('google') },
    other: { leadsPerMonth: Number(sc.otherLeads) || 0, rates, winRate },
    baseSpend: { meta: Number(sc.metaSpend) || 0, google: Number(sc.googleSpend) || 0 },
    avgDeal: Number(sc.avgDeal) || 0, avgDealBasis: 'typed',
    wonIsLastStage: true,
    grossMargin: sc.grossMargin, purchases: sc.purchases, ltv: sc.ltv,
  }
}
// A scenario seeded from a live client, so "what if" starts from what is.
function fcScenarioFromModel(model, spend, name) {
  const rates = model.channels.meta.own ? model.channels.meta.rates : (model.channels.google.own ? model.channels.google.rates : model.other.rates)
  const winAll = model.sample ? ((model.sample.won.meta + model.sample.won.google + model.sample.won.other) / Math.max(1, model.sample.leads.meta + model.sample.leads.google + model.sample.leads.other)) : 0
  // A client's stages end wherever its pipeline ends; the win sits after them.
  // The scenario gets a final "Won" stage whose step is the win as a share of
  // whatever reached the last real stage, so the funnel closes on the win.
  const lastReach = rates.length ? rates[rates.length - 1] : 1
  const steps = fcRatesToSteps([...rates, Math.min(winAll, lastReach || winAll)])
  return {
    id: `sc_${Date.now().toString(36)}`, name: name || `${model.pipeName} - what if`,
    metaSpend: Math.round(spend.meta || 0), googleSpend: Math.round(spend.google || 0),
    metaCpl: model.channels.meta.cpl ? Math.round(model.channels.meta.cpl) : '', googleCpl: model.channels.google.cpl ? Math.round(model.channels.google.cpl) : '',
    otherLeads: Math.round(model.other.leadsPerMonth || 0),
    stages: [...model.stages.map((s, i) => ({ name: s.name, step: steps[i] })), { name: 'Won', step: steps[steps.length - 1] }],
    avgDeal: Math.round(model.avgDeal || 0),
    grossMargin: model.grossMargin ?? '', purchases: model.purchases || 1, ltv: '',
    cplRise: 0,
  }
}

// --- storage ----------------------------------------------------------------
function loadScenarios() { return Object.values(SETTINGS.forecasts || {}).filter((s) => s && s.id).sort((a, b) => (b.at || 0) - (a.at || 0)) }
function saveScenario(sc) {
  const next = { ...(SETTINGS.forecasts || {}), [sc.id]: { ...sc, at: Date.now() } }
  SETTINGS.forecasts = next; writeLS(FORECAST_KEY, next); saveSettingsRemote({ forecasts: { [sc.id]: next[sc.id] } }); bumpSettings()
}
function deleteScenario(id) {
  const next = { ...(SETTINGS.forecasts || {}) }; delete next[id]
  SETTINGS.forecasts = next; writeLS(FORECAST_KEY, next); saveSettingsRemote({ forecasts: { [id]: null } }); bumpSettings()
}

// --- the funnel picture ------------------------------------------------------
// Stacked horizontal bars, widest at the top, one colour per channel - drawn
// with plain elements so the numbers sit exactly where the bars end and it
// prints. Each row: name, the three segments, the forecast count, the step
// conversion from the row above, and what each one costs at this spend.
function FcFunnel({ fc, model, money, compare }) {
  const rows = [{ key: '__leads', name: 'Leads', meta: fc.leads.meta, google: fc.leads.google, other: fc.leads.other, total: fc.leads.total, step: null, costEach: fc.paidCpl }, ...fc.stages]
  const wonIsLast = !!model.wonIsLastStage
  const max = Math.max(1, ...rows.map((r) => r.total))
  const n0 = (v) => fmtNumber(Math.round(v))
  return (
    <div className="fc-funnel">
      {rows.map((r, i) => {
        const w = (r.total / max) * 100
        const cmp = compare && (i === 0 ? compare.leads : compare.stages[i - 1])
        return (
          <div className="fc-row" key={r.key}>
            <div className="fc-name" title={r.name}>{r.name}</div>
            <div className="fc-track">
              <div className="fc-bar" style={{ width: `${Math.max(w, 0.5)}%` }} title={`${n0(r.meta)} Meta · ${n0(r.google)} Google · ${n0(r.other)} non-paid`}>
                {r.total > 0 && FC_CHANNELS.map(([c, , col]) => <span key={c} style={{ width: `${(r[c] / r.total) * 100}%`, background: col }} />)}
              </div>
              <span className="fc-val">{n0(r.total)}{cmp != null ? <small className={r.total >= cmp ? 'up' : 'dn'}> vs {n0(cmp)}</small> : null}</span>
            </div>
            <div className="fc-step">{r.step != null ? `${Math.round(r.step * 100)}%` : ''}</div>
            <div className="fc-cost">{r.costEach != null && isFinite(r.costEach) ? money(Math.round(r.costEach)) : '-'}</div>
          </div>
        )
      })}
      <div className="fc-row fc-row-won">
        <div className="fc-name">{wonIsLast ? `Won · ${(rows[rows.length - 1] || {}).name || ''}` : 'Won'}</div>
        <div className="fc-track"><span className="fc-val fc-val-won">{n0(fc.won.total)}<small> · {money(Math.round(fc.revenue))}</small></span></div>
        <div className="fc-step" title="Share of all leads that are won">{fc.leads.total ? `${Math.round((fc.won.total / fc.leads.total) * 100)}%` : ''}</div>
        <div className="fc-cost">{fc.cac != null ? money(Math.round(fc.cac)) : '-'}</div>
      </div>
      <div className="fc-legend">
        {FC_CHANNELS.map(([c, l, col]) => <span key={c}><i style={{ background: col }} />{l}</span>)}
        <span className="fc-legend-k">step % = share of the stage above · cost = total spend ÷ reached</span>
      </div>
    </div>
  )
}

// Spend from half to double the current level, and what each level buys. The
// one chart that answers "is more budget worth it" in a glance.
function FcCurve({ model, spend, opts, money }) {
  const total = (spend.meta || 0) + (spend.google || 0)
  if (!total) return null
  const split = { meta: (spend.meta || 0) / total, google: (spend.google || 0) / total }
  const pts = []
  for (let f = 0.5; f <= 2.0001; f += 0.125) {
    const s = total * f
    const fc = fcForecast(model, { meta: s * split.meta, google: s * split.google }, opts)
    pts.push({ spend: Math.round(s), leads: Math.round(fc.leads.meta + fc.leads.google), won: Math.round((fc.won.meta + fc.won.google) * 10) / 10, cac: fc.cac ? Math.round(fc.cac) : null, now: Math.abs(f - 1) < 0.01 })
  }
  return (
    <div className="fc-curve">
      <div className="fc-curve-h">Spend against outcome <span className="sub">· half to double today's budget, same channel mix{opts.cplRise ? ' · with rising CPL' : ''}</span></div>
      <ResponsiveContainer width="100%" height={190}>
        <ComposedChart data={pts} margin={{ top: 6, right: 12, bottom: 2, left: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
          <XAxis dataKey="spend" tick={{ fontSize: 10, fill: 'var(--muted)' }} tickFormatter={(v) => money(v)} axisLine={false} tickLine={false} />
          <YAxis yAxisId="l" tick={{ fontSize: 10, fill: 'var(--muted)' }} axisLine={false} tickLine={false} allowDecimals={false} />
          <YAxis yAxisId="r" orientation="right" tick={{ fontSize: 10, fill: 'var(--muted)' }} axisLine={false} tickLine={false} tickFormatter={(v) => money(v)} />
          <Tooltip contentStyle={{ fontSize: 12 }} formatter={(v, n) => [n === 'CAC' ? money(v) : fmtNumber(v), n]} labelFormatter={(v) => `Spend ${money(v)} / month`} />
          <Bar yAxisId="l" dataKey="leads" name="Paid leads" fill="#4f7cff" fillOpacity={0.35} maxBarSize={22} />
          <Line yAxisId="l" dataKey="won" name="Won" stroke="#12b886" strokeWidth={2.5} dot={false} />
          <Line yAxisId="r" dataKey="cac" name="CAC" stroke="#e0803a" strokeWidth={2} strokeDasharray="5 4" dot={false} />
          <ReferenceLine yAxisId="l" x={Math.round(total)} stroke="var(--text)" strokeDasharray="4 3" label={{ value: 'today', fontSize: 10, fill: 'var(--muted)', position: 'top' }} />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  )
}

function FcSpendInputs({ spend, setSpend, base, money, opts, setOpts, channels, share = 1 }) {
  const total = (spend.meta || 0) + (spend.google || 0)
  return (
    <div className="fc-inputs">
      {['meta', 'google'].map((c) => {
        const ch = channels[c]
        const off = !ch || !ch.cpl
        return (
          <div className={`fc-in${off ? ' off' : ''}`} key={c}>
            <div className="fc-in-h"><span className="ov-pd" style={{ background: c === 'meta' ? '#4f7cff' : '#12b886' }}>{c === 'meta' ? 'Meta' : 'Google'}</span> spend / month
              {off ? <span className="cap"> · no cost per lead on record</span> : <span className="cap"> · {money(Math.round(ch.cpl))} per lead{ch.cplBasis && ch.cplBasis !== 'typed' ? ` (${ch.cplBasis})` : ''}</span>}
            </div>
            <div className="fc-in-row">
              <input type="range" min={0} max={Math.max(1000, Math.round((base[c] || 0) * 3), Math.round(spend[c] || 0))} step={50} value={Math.round(spend[c] || 0)} disabled={off} onChange={(e) => setSpend({ ...spend, [c]: Number(e.target.value) })} />
              <span className="fc-in-cur">$</span>
              <input type="number" min={0} step={50} value={Math.round(spend[c] || 0)} disabled={off} onChange={(e) => setSpend({ ...spend, [c]: Math.max(0, Number(e.target.value) || 0) })} />
            </div>
            {base[c] > 0 && Math.abs((spend[c] || 0) - base[c]) > 1 ? <div className="cap">{(spend[c] || 0) > base[c] ? '+' : ''}{Math.round((((spend[c] || 0) - base[c]) / base[c]) * 100)}% on the last 30 days ({money(Math.round(base[c]))}{share < 1 ? `, this pipeline's ${Math.round(share * 100)}% share` : ''})</div> : base[c] > 0 ? <div className="cap">Last 30 days: {money(Math.round(base[c]))}{share < 1 ? ` · this pipeline's ${Math.round(share * 100)}% share of the account` : ''}</div> : null}
          </div>
        )
      })}
      <div className="fc-in fc-in-total">
        <div className="fc-in-h">Total <b>{money(Math.round(total))}</b> / month</div>
        <label className="fc-opt" title="Doubling spend rarely doubles leads: auctions get more expensive as you buy more of them. This raises cost per lead by the chosen amount for every +50% of spend above the last 30 days. An assumption, not a measurement.">
          <input type="checkbox" checked={!!opts.cplRise} onChange={(e) => setOpts({ ...opts, cplRise: e.target.checked ? 0.15 : 0 })} /> Diminishing returns
          {opts.cplRise ? <select value={String(opts.cplRise)} onChange={(e) => setOpts({ ...opts, cplRise: Number(e.target.value) })}>{[0.1, 0.15, 0.25, 0.4].map((v) => <option key={v} value={String(v)}>CPL +{Math.round(v * 100)}% per +50% spend</option>)}</select> : null}
        </label>
        <label className="fc-opt" title="Leads that arrive without ads - organic, referral, direct. They do not move with spend, so they are shown as a flat baseline."><input type="checkbox" checked={opts.includeOther !== false} onChange={(e) => setOpts({ ...opts, includeOther: e.target.checked })} /> Include non-paid baseline</label>
      </div>
    </div>
  )
}

function FcHeadline({ fc, model, money }) {
  const n0 = (v) => fmtNumber(Math.round(v))
  const e = fc.econ || {}
  const x1 = (v) => (v == null || !isFinite(v) ? '-' : `${v.toFixed(1)}×`)
  const signed = (v) => (v == null || !isFinite(v) ? '-' : `${v < 0 ? '−' : ''}${money(Math.round(Math.abs(v)))}`)
  const hasEcon = e.margin != null || e.purchases > 1 || Number(model.ltv) > 0
  return (
    <>
      <div className="scorecard sc-fit fc-head">
        <Sc label="Paid leads / month" value={n0(fc.leads.meta + fc.leads.google)} tip="Spend ÷ cost per lead, per channel" />
        <Sc label="Cost per lead" value={fc.paidCpl ? money(Math.round(fc.paidCpl)) : '-'} />
        <Sc label="Won / month" value={n0(fc.won.total)} tip={`Paid ${n0(fc.won.meta + fc.won.google)} · non-paid ${n0(fc.won.other)}`} />
        <Sc label="CAC" value={fc.cac ? money(Math.round(fc.cac)) : '-'} tip="Spend ÷ paid wins" />
        <Sc label="Revenue / month" value={money(Math.round(fc.revenue))} tip={`Won × ${money(Math.round(model.avgDeal || 0))} (${model.avgDealBasis})`} />
        <Sc label="Return on spend" value={x1(fc.roas)} tip="Paid revenue ÷ spend" />
      </div>
      {hasEcon ? (
        <div className="scorecard sc-fit fc-head fc-econ">
          <Sc label="Gross profit / month" value={e.grossProfit != null ? money(Math.round(e.grossProfit)) : '-'} tip={e.margin != null ? `Revenue × ${Math.round(e.margin * 100)}% gross margin` : 'Set a gross margin'} />
          <Sc label="LTV" value={money(Math.round(e.ltv || 0))} tip={Number(model.ltv) > 0 ? 'Typed lifetime value' : `${money(Math.round(model.avgDeal || 0))} × ${e.purchases} purchases per customer`} />
          <Sc label="LTV : CAC" value={x1(e.ltvCac)} tip="Lifetime revenue per customer ÷ cost to win one. 3× is the usual floor for a healthy funnel." />
          <Sc label="LTV-GP : CAC" value={x1(e.ltvGpCac)} tip={e.margin != null ? 'Lifetime GROSS PROFIT per customer ÷ cost to win one - whether the business keeps anything' : 'Set a gross margin'} />
          <Sc label="Net of ad spend" value={signed(e.netOfSpend)} tip="Revenue − spend, this month" />
          <Sc label="Contribution" value={signed(e.contribution)} tip={e.margin != null ? 'Gross profit − spend: what is left after goods and ads' : 'Set a gross margin'} />
        </div>
      ) : null}
    </>
  )
}

// --- the client forecast -----------------------------------------------------
function FcClient({ clients, currency, nonce, onSaveScenario }) {
  const [cid, setCid] = useState(clients[0]?.id || null)
  const [pid, setPid] = useState('')
  const [spend, setSpendRaw] = useState(null)   // null = follow the client's last 30 days until touched
  const [opts, setOpts] = useState({ cplRise: 0, includeOther: true })
  const r90 = useMemo(() => presetRange('last_90d'), [])
  const r30 = useMemo(() => presetRange('last_30d'), [])
  const d90 = useCcDrill(cid, r90, nonce, 'all', 'created')
  const d30 = useCcDrill(cid, r30, nonce, 'all', 'created')
  const money = (v) => fmtCurrency(v, currency)
  useEffect(() => { setPid(''); setSpendRaw(null) }, [cid])
  const pipes = (d90.data && d90.data.pipelinesFunnel) || []
  useEffect(() => { if (pipes.length && !pipes.some((p) => p.id === pid)) setPid(pipes[0].id) }, [pipes.length]) // eslint-disable-line
  const model = useMemo(() => (d90.data && d30.data ? fcModelFromClient(d90.data, d30.data, pid, loadKpis(cid, pid || undefined)) : null), [d90.data, d30.data, pid, cid])
  const base = model ? model.baseSpend : { meta: 0, google: 0 }
  const live = spend || base
  const fc = useMemo(() => (model ? fcForecast(model, live, opts) : null), [model, live, opts])
  // What the same model says about the LAST 30 days, at last month's spend: a
  // sanity check that the average reproduces the recent past before it is
  // trusted forward.
  const actual = d30.data && model ? (() => {
    const p = (d30.data.pipelinesFunnel || []).find((x) => x.id === model.pipeId)
    const c = ((d30.data.pipeContribution || []).find((x) => x.id === model.pipeId) || {}).chan
    if (!p || !c) return null
    return { leads: (c.meta.leads || 0) + (c.google.leads || 0) + (c.other.leads || 0), stages: model.stages.map((s) => ((p.stages || []).find((x) => x.id === s.key) || {}).count || 0) }
  })() : null
  const loading = d90.status === 'loading' || d30.status === 'loading'
  return (
    <>
      <div className="fc-bar">
        <label className="fc-pick"><span className="cap">Client</span>
          <select value={cid || ''} onChange={(e) => setCid(e.target.value)}>{clients.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
        {pipes.length > 1 ? <label className="fc-pick"><span className="cap">Pipeline</span>
          <select value={pid} onChange={(e) => { setPid(e.target.value); setSpendRaw(null) }}>{pipes.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label> : null}
        {model ? <button className="btn-ghost sm" onClick={() => onSaveScenario(fcScenarioFromModel(model, live))} title="Copy these numbers into the scenario builder to change anything about them">Open as a scenario →</button> : null}
        {spend ? <button className="btn-ghost sm" onClick={() => setSpendRaw(null)}>Reset to last 30 days</button> : null}
      </div>
      {loading && !model ? <TabLoading kind="table" label="Reading the last 90 days…" />
        : !model ? <div className="card empty-deep"><div className="big">📉</div><b>Nothing to forecast from.</b><p>{cid ? 'This client has no pipeline activity in the last 90 days, or no CRM connection.' : 'Pick a client.'}</p></div>
          : <>
            <FcHeadline fc={fc} model={model} money={money} />
            <div className="card">
              <FcSpendInputs spend={live} setSpend={setSpendRaw} base={base} money={money} opts={opts} setOpts={setOpts} channels={model.channels} share={model.spendShare || 1} />
            </div>
            <div className="card">
              <div className="exec-panel-h">{model.pipeName} <span className="sub">· forecast month at {money(Math.round(fc.spend.total))} · stage rates from the last 90 days, cost per lead from the last 30</span></div>
              <FcFunnel fc={fc} model={model} money={money} compare={spend ? null : actual} />
              <FcCurve model={model} spend={live} opts={opts} money={money} />
              <Caveat>
                Everything here is an average applied forward - "if next month behaves like the last three" - so it is a planning number, not a promise.
                {' '}Paid leads scale with spend; the non-paid baseline ({fmtNumber(Math.round(model.other.leadsPerMonth))} leads a month from organic, referral and direct) does not.
                {' '}Stage rates are per channel where the channel has {FC_MIN_CHANNEL_LEADS}+ leads in the sample{!model.channels.meta.own || !model.channels.google.own ? ` - ${[!model.channels.meta.own && 'Meta', !model.channels.google.own && 'Google'].filter(Boolean).join(' and ')} borrow${!model.channels.meta.own && !model.channels.google.own ? '' : 's'} the blended curve` : ''}.
                {' '}Sample: {fmtNumber(model.sample.leads.meta + model.sample.leads.google + model.sample.leads.other)} leads, {fmtNumber(model.sample.won.meta + model.sample.won.google + model.sample.won.other)} won, in 90 days.
                {!spend && actual ? ' The grey "vs" figures are what actually happened in the last 30 days at that spend - if the forecast is far from them, the last month was unusual and the average should be read with that in mind.' : ''}
              </Caveat>
            </div>
          </>}
    </>
  )
}

// --- the scenario builder ----------------------------------------------------
const FC_BLANK = () => ({ id: `sc_${Date.now().toString(36)}`, name: 'New scenario', metaSpend: 3000, googleSpend: 2000, metaCpl: 40, googleCpl: 60, otherLeads: 0,
  stages: [{ name: 'Booked call', step: 60 }, { name: 'Showed', step: 70 }, { name: 'Quoted', step: 80 }, { name: 'Won', step: 35 }], avgDeal: 2500, grossMargin: '', purchases: 1, ltv: '', cplRise: 0 })
function FcBuilder({ currency, seed, onSeeded }) {
  useSettingsSync()
  const saved = loadScenarios()
  const [sc, setSc] = useState(() => seed || saved[0] || FC_BLANK())
  const [dirty, setDirty] = useState(!!seed)
  const [confirmDel, setConfirmDel] = useState(false)
  useEffect(() => { setConfirmDel(false) }, [sc.id])
  useEffect(() => { if (seed) { setSc(seed); setDirty(true); onSeeded && onSeeded() } }, [seed]) // eslint-disable-line
  const money = (v) => fmtCurrency(v, currency)
  const up = (patch) => { setSc((p) => ({ ...p, ...patch })); setDirty(true) }
  const upStage = (i, patch) => up({ stages: sc.stages.map((s, j) => (j === i ? { ...s, ...patch } : s)) })
  const model = useMemo(() => fcModelFromScenario(sc), [sc])
  const spend = { meta: Number(sc.metaSpend) || 0, google: Number(sc.googleSpend) || 0 }
  const opts = { cplRise: Number(sc.cplRise) || 0, includeOther: true }
  const fc = useMemo(() => fcForecast(model, spend, opts), [model, sc.metaSpend, sc.googleSpend, sc.cplRise])
  const n1 = (v) => (v == null || v === '' ? '' : v)
  return (
    <>
      <div className="fc-bar">
        <label className="fc-pick"><span className="cap">Scenario</span>
          <select value={saved.some((s) => s.id === sc.id) ? sc.id : '__cur'} onChange={(e) => { if (e.target.value === '__new') { setSc(FC_BLANK()); setDirty(true) } else { const s = saved.find((x) => x.id === e.target.value); if (s) { setSc(s); setDirty(false) } } }}>
            {!saved.some((s) => s.id === sc.id) ? <option value="__cur">{sc.name}{dirty ? ' (unsaved)' : ''}</option> : null}
            {saved.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
            <option value="__new">+ New scenario</option>
          </select></label>
        <input className="inp fc-name-in" value={sc.name} onChange={(e) => up({ name: e.target.value })} placeholder="Scenario name" />
        <button className="set-details-save" disabled={!dirty} onClick={() => { saveScenario(sc); setDirty(false) }}>{dirty ? 'Save scenario' : '✓ Saved'}</button>
        {saved.some((s) => s.id === sc.id) ? (confirmDel
          ? <span className="fc-del"><span className="cap">Delete “{sc.name}” for everyone?</span><button className="btn-danger sm" onClick={() => { deleteScenario(sc.id); setSc(saved.find((s) => s.id !== sc.id) || FC_BLANK()); setDirty(false); setConfirmDel(false) }}>Yes, delete</button><button className="btn-ghost sm" onClick={() => setConfirmDel(false)}>Keep</button></span>
          : <button className="btn-ghost sm" onClick={() => setConfirmDel(true)} title="Remove this saved scenario for the whole team">Delete</button>) : null}
        <span className="cap">Saved scenarios are shared with the team.</span>
      </div>
      <FcHeadline fc={fc} model={model} money={money} />
      <div className="fc-build">
        <div className="card fc-build-in">
          <div className="exec-panel-h">Inputs</div>
          <div className="fc-grid2">
            <label>Meta spend / month<input type="number" min="0" step="50" value={n1(sc.metaSpend)} onChange={(e) => up({ metaSpend: e.target.value })} /></label>
            <label>Meta cost / lead<input type="number" min="0" value={n1(sc.metaCpl)} onChange={(e) => up({ metaCpl: e.target.value })} /></label>
            <label>Google spend / month<input type="number" min="0" step="50" value={n1(sc.googleSpend)} onChange={(e) => up({ googleSpend: e.target.value })} /></label>
            <label>Google cost / lead<input type="number" min="0" value={n1(sc.googleCpl)} onChange={(e) => up({ googleCpl: e.target.value })} /></label>
            <label title="Leads a month that arrive without ads. They flow through the same stages but do not move with spend.">Non-paid leads / month<input type="number" min="0" value={n1(sc.otherLeads)} onChange={(e) => up({ otherLeads: e.target.value })} /></label>
            <label title="Raises cost per lead by this much for every +50% of spend over the typed spend. Leave at 0 to scale in a straight line.">CPL rise per +50% spend<div className="fc-pct"><input type="number" min="0" max="100" value={Math.round((Number(sc.cplRise) || 0) * 100)} onChange={(e) => up({ cplRise: Math.max(0, Number(e.target.value) || 0) / 100 })} /><span>%</span></div></label>
          </div>
          <div className="exec-panel-h" style={{ marginTop: 14 }}>Stages <span className="sub">· each as a share of the one before it</span></div>
          <div className="fc-stages">
            <div className="fc-stage fc-stage-head"><span>Leads</span><span className="cap">100% · the top</span></div>
            {sc.stages.map((s, i) => (
              <div className="fc-stage" key={i}>
                <input className="inp" value={s.name} onChange={(e) => upStage(i, { name: e.target.value })} placeholder={`Stage ${i + 1}`} />
                <div className="fc-pct"><input type="number" min="0" max="100" value={n1(s.step)} onChange={(e) => upStage(i, { step: e.target.value })} title={`Share of ${i ? sc.stages[i - 1].name || 'the stage above' : 'leads'} that reach this stage - a show rate, a quote rate, a booking rate`} /><span>%</span></div>
                <span className="fc-stage-of cap">{Math.round(fcStepsToRates(sc.stages.map((x) => x.step))[i] * 100)}% of leads</span>
                <button className="icon-btn sm" title="Remove this stage" onClick={() => up({ stages: sc.stages.filter((_, j) => j !== i) })}>✕</button>
              </div>
            ))}
            <button className="btn-ghost sm" onClick={() => up({ stages: [...sc.stages, { name: '', step: 50 }] })}>+ Add a stage</button>
          </div>
          <p className="cap" style={{ margin: '6px 0 0' }}>The last stage is the win - <b>{(sc.stages[sc.stages.length - 1] || {}).name || 'the final stage'}</b> is what gets counted as won and priced.</p>
          <div className="fc-grid2" style={{ marginTop: 14 }}>
            <label>Average deal value<input type="number" min="0" value={n1(sc.avgDeal)} onChange={(e) => up({ avgDeal: e.target.value })} /></label>
          </div>
          <details className="fc-adv" open={sc.grossMargin !== '' && sc.grossMargin != null}>
            <summary>Advanced · margins and lifetime value</summary>
            <div className="fc-grid2" style={{ marginTop: 10 }}>
              <label title="Share of each deal's revenue left after the cost of delivering it - before ad spend. Turns on gross profit, LTV-GP:CAC and contribution below.">Gross margin<div className="fc-pct"><input type="number" min="0" max="100" value={n1(sc.grossMargin)} onChange={(e) => up({ grossMargin: e.target.value })} placeholder="e.g. 60" /><span>%</span></div></label>
              <label title="How many times the average customer buys over their lifetime, this deal included. LTV = deal value x this, unless a lifetime value is typed.">Purchases per customer<input type="number" min="1" step="0.5" value={n1(sc.purchases)} onChange={(e) => up({ purchases: e.target.value })} placeholder="1" /></label>
              <label title="Type a lifetime value directly if you know it; it overrides deal x purchases.">Lifetime value (override)<input type="number" min="0" value={n1(sc.ltv)} onChange={(e) => up({ ltv: e.target.value })} placeholder={`${Math.round((Number(sc.avgDeal) || 0) * (Number(sc.purchases) || 1))} from deal × purchases`} /></label>
            </div>
          </details>
        </div>
        <div className="card">
          <div className="exec-panel-h">{sc.name || 'Scenario'} <span className="sub">· forecast month at {money(Math.round(fc.spend.total))}</span></div>
          <FcFunnel fc={fc} model={model} money={money} />
          <FcCurve model={model} spend={spend} opts={opts} money={money} />
          <Caveat>A scenario is only as good as its inputs. "Open as a scenario" from a client forecast seeds every field from that client's real last 90 days, which is a better place to start than a guess.</Caveat>
        </div>
      </div>
    </>
  )
}

function FunnelForecaster({ rows, currency, nonce }) {
  const clients = useMemo(() => [...rows].filter((c) => c.c && c.c.ghl).sort((a, b) => a.name.localeCompare(b.name)), [rows])
  const [mode, setMode] = useState('client')
  const [seed, setSeed] = useState(null)
  return (
    <div className="fc-wrap">
      <div className="optlog-toggle fc-mode">
        <button className={mode === 'client' ? 'on' : ''} onClick={() => setMode('client')}>Client forecast</button>
        <button className={mode === 'builder' ? 'on' : ''} onClick={() => setMode('builder')}>Scenario builder</button>
      </div>
      {mode === 'client'
        ? <FcClient clients={clients} currency={currency} nonce={nonce} onSaveScenario={(sc) => { setSeed(sc); setMode('builder') }} />
        : <FcBuilder currency={currency} seed={seed} onSeeded={() => setSeed(null)} />}
    </div>
  )
}

function WeeklyTab({ rows, currency, nonce, wonBasis = 'closed' }) {
  const clients = [...rows].sort((a, b) => a.name.localeCompare(b.name))
  const [cid, setCid] = useState(clients[0]?.id || null)
  const [weeks, setWeeks] = useState(6)
  const wk = useWeekly(cid, weeks, nonce, wonBasis)
  const kpis = cid ? loadKpis(cid) : {}
  const money = (v) => fmtCurrency(v, currency)
  const clientName = clients.find((c) => c.id === cid)?.name || '-'
  const [ai, setAi] = useState(() => (cid ? loadInsights(cid) : null))
  const [aiLoading, setAiLoading] = useState(false)
  const [aiErr, setAiErr] = useState(null)
  // Re-read once server settings hydrate (SETTINGS.loaded) so a briefing saved
  // on another device/browser shows up here too.
  useEffect(() => { setAi(cid ? loadInsights(cid) : null); setAiErr(null) }, [cid, SETTINGS.loaded])
  const genInsights = async () => {
    if (!wk.data || !wk.data.weeks || aiLoading) return
    setAiLoading(true); setAiErr(null)
    try {
      const r = await fetch('/.netlify/functions/insights', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ clientName, weekly: wk.data, kpis }) })
      const j = await r.json().catch(() => ({}))
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`)
      const rec = { insights: j.insights, weekRange: j.weekRange, generatedAt: j.generatedAt || new Date().toISOString(), model: j.model }
      saveInsights(cid, rec); setAi(rec)
    } catch (e) { setAiErr(String(e.message || e)) } finally { setAiLoading(false) }
  }
  return (
    <>
      <div className="c360-head" style={{ marginTop: 0 }}>
        <div className="pipe-sel"><label>Client</label>
          <select value={cid || ''} onChange={(e) => setCid(e.target.value)}>{[...clients].sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' })).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
        </div>
        <div className="pipe-sel"><label>Weeks</label>
          <select value={weeks} onChange={(e) => setWeeks(Number(e.target.value))}>{[4, 6, 8, 12].map((n) => <option key={n} value={n}>Last {n} weeks</option>)}</select>
        </div>
      </div>
      {wk.status === 'loading' ? <TabLoading kind="table" label="Loading weekly data…" />
        : wk.status === 'err' || !wk.data || !wk.data.weeks ? <div className="card"><p className="cap" style={{ margin: 0 }}>Couldn't load weekly data - try Refresh.</p></div>
          : (() => {
            const W = wk.data.weeks.map((w) => ({
              ...w,
              cpl: w.leads ? w.spend / w.leads : 0,
              metaCplV: w.metaLeads ? w.metaSpend / w.metaLeads : 0,
              gCostConv: w.googleConv ? w.googleSpend / w.googleConv : 0,
              cpba: w.booked ? w.spend / w.booked : 0,
              bookingRate: w.leads ? (w.booked / w.leads) * 100 : 0,
              showRate: w.booked ? (w.shown / w.booked) * 100 : 0,
              cpa: w.won ? w.spend / w.won : 0,
            }))
            const T = W.reduce((a, w) => ({ spend: a.spend + w.spend, metaSpend: a.metaSpend + w.metaSpend, metaLeads: a.metaLeads + w.metaLeads, leads: a.leads + w.leads, booked: a.booked + w.booked, shown: a.shown + w.shown, won: a.won + w.won, wonValue: a.wonValue + w.wonValue }), { spend: 0, metaSpend: 0, metaLeads: 0, leads: 0, booked: 0, shown: 0, won: 0, wonValue: 0 })
            const n = W.length || 1
            const avgSpend = T.spend / n
            const mCpl = T.metaLeads ? T.metaSpend / T.metaLeads : 0
            const aCpl = T.leads ? T.spend / T.leads : 0
            const cpba = T.booked ? T.spend / T.booked : 0
            const bookRate = T.leads ? (T.booked / T.leads) * 100 : 0
            const cpa = T.won ? T.spend / T.won : 0
            const avgDeal = T.won ? T.wonValue / T.won : 0
            const roas = T.spend ? T.wonValue / T.spend : 0
            const fmtD = (ds) => { try { return new Date(ds + 'T00:00:00Z').toLocaleDateString('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' }) } catch { return ds } }
            const endSun = W.length ? (() => { const d = new Date(W[W.length - 1].week + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 6); return d.toISOString().slice(0, 10) })() : null
            const rangeLbl = W.length ? `${W[0].label} to ${W[W.length - 1].label} · ${fmtD(W[0].week)} to ${fmtD(endSun)}` : ''
            return (
              <>
                <div className="section-title" style={{ marginTop: 4 }}>{clientName} <span className="sub">· weekly (Mon to Sun) · {rangeLbl}</span></div>
                <div className="wk-tiles wk-tiles-9">
                  <WkTile label="Pacing (avg/wk)" value={money(avgSpend)} num={avgSpend} target={kpis.wkSpend} goodWhenDown />
                  <WkTile label="Meta CPL" value={mCpl ? money(mCpl) : '-'} num={mCpl} target={kpis.metaCpl} goodWhenDown />
                  <WkTile label="All Leads CPL" value={aCpl ? money(aCpl) : '-'} num={aCpl} target={kpis.cpl} goodWhenDown />
                  <WkTile label="Booking Rate" value={fmtPct(bookRate, 1)} num={bookRate} target={kpis.bookingRate} goodWhenDown={false} />
                  <WkTile label="CPA (cost/won)" value={cpa ? money(cpa) : '-'} num={cpa} target={kpis.cpa} goodWhenDown />
                  <WkTile label={<>Won Value <WonBasisChip basis={wonBasis} /></>} value={money(T.wonValue)} num={null} />
                  <WkTile label="Avg Deal Value" value={T.won ? money(avgDeal) : '-'} num={null} />
                  <WkTile label="ROAS" value={`${roas.toFixed(2)}×`} num={null} />
                </div>
                <div className="card ai-card" style={{ marginTop: 14 }}>
                  <div className="ai-head">
                    <div className="ai-title">✨ AI insights {ai ? <span className="sub">· {ai.weekRange} · generated {new Date(ai.generatedAt).toLocaleString('en-AU')}</span> : <span className="sub">· Claude reads Meta + Google vs CRM outcomes</span>}</div>
                    <button className="ai-btn" onClick={genInsights} disabled={aiLoading}>{aiLoading ? 'Generating…' : ai ? '↻ Regenerate' : '✨ Generate AI insights'}</button>
                  </div>
                  {aiErr && <p className="cap" style={{ color: 'var(--neg)', margin: '2px 0 0' }}>{aiErr}</p>}
                  {aiLoading ? <Spinner label="Claude is analysing this client…" />
                    : ai ? <MdText text={ai.insights} />
                      : <p className="cap" style={{ margin: 0 }}>Generate a written briefing that interprets this client's weekly Meta / Google performance against their Caalano Systems bookings, wins and lost reasons. It only runs when you click, and stays saved to this client until you regenerate.</p>}
                </div>
                <div className="wk-grid">
                  <div className="card chart-card"><h3>Overall Spend Pacing</h3><p className="cap">Spend per week vs weekly target</p>
                    <ResponsiveContainer width="100%" height={240}><ComposedChart data={W} margin={{ left: -4, right: 6, top: 10 }}>
                      <CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="label" fontSize={11} stroke="var(--muted)" /><YAxis fontSize={10} stroke="var(--muted)" tickFormatter={(v) => '$' + fmtCompact(v)} /><Tooltip formatter={(v) => money(v)} />
                      <Bar dataKey="spend" name="Spend" fill="#e2504f" radius={[3, 3, 0, 0]} maxBarSize={46} />
                      {Number(kpis.wkSpend) > 0 && <ReferenceLine y={Number(kpis.wkSpend)} stroke="var(--text)" strokeDasharray="5 4" label={{ value: `KPI ${money(kpis.wkSpend)}`, fontSize: 10, fill: 'var(--muted)', position: 'insideTopRight' }} />}
                    </ComposedChart></ResponsiveContainer>
                  </div>
                  <div className="card chart-card"><h3>All Leads</h3><p className="cap">Lead volume (bars) &amp; all-leads CPL (line) by week</p>
                    <WkDual data={W} costKey="cpl" costName="CPL" countKey="leads" countName="Leads" kpi={Number(kpis.cpl) || null} currency={currency} costColor="#f5a524" countColor="#ffe2b0" />
                  </div>
                  {wk.data.hasMeta && <div className="card chart-card"><h3>Meta Leads</h3><p className="cap">Leads (bars) &amp; Meta CPL (line) by week</p>
                    <WkDual data={W} costKey="metaCplV" costName="CPL" countKey="metaLeads" countName="Leads" kpi={Number(kpis.metaCpl) || null} currency={currency} costColor="#4f7cff" countColor="#bcd0ff" />
                  </div>}
                  {wk.data.hasGoogle && <div className="card chart-card"><h3>Google Leads</h3><p className="cap">Conversions (bars) &amp; cost per conversion (line) by week</p>
                    <WkDual data={W} costKey="gCostConv" costName="Cost/conv" countKey="googleConv" countName="Conv." kpi={Number(kpis.googleCostConv) || null} currency={currency} costColor="#0e8f6a" countColor="#a7e8d3" />
                  </div>}
                  {wk.data.hasCrm && <>
                    <div className="card chart-card"><h3>Appointments Booked</h3><p className="cap">Booked appointments by week</p>
                      <ResponsiveContainer width="100%" height={240}><BarChart data={W} margin={{ left: -4, right: 6, top: 14 }}>
                        <CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="label" fontSize={11} stroke="var(--muted)" /><YAxis fontSize={10} stroke="var(--muted)" allowDecimals={false} /><Tooltip formatter={(v) => fmtNumber(v)} />
                        <Bar dataKey="booked" name="Appt's" fill="#b0325f" radius={[3, 3, 0, 0]} maxBarSize={46}><LabelList dataKey="booked" position="insideTop" fill="#fff" fontSize={10} fontWeight={700} formatter={(v) => (v ? fmtNumber(v) : '')} /></Bar>
                      </BarChart></ResponsiveContainer>
                    </div>
                    <div className="card chart-card"><h3>Shown Appointments</h3><p className="cap">Shown (bars) &amp; show rate (line) by week</p>
                      <ResponsiveContainer width="100%" height={240}><ComposedChart data={W} margin={{ left: -4, right: 6, top: 10 }}>
                        <CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="label" fontSize={11} stroke="var(--muted)" /><YAxis yAxisId="l" fontSize={10} stroke="var(--muted)" tickFormatter={(v) => v + '%'} /><YAxis yAxisId="r" orientation="right" fontSize={10} stroke="var(--muted)" allowDecimals={false} /><Tooltip formatter={(v, nm) => (nm === 'Show rate' ? fmtPct(v, 1) : fmtNumber(v))} /><Legend />
                        <Bar yAxisId="r" dataKey="shown" name="Shown" fill="#2f8f83" radius={[3, 3, 0, 0]} maxBarSize={42} />
                        <Line yAxisId="l" type="monotone" dataKey="showRate" name="Show rate" stroke="#8fcabe" strokeWidth={2.5} dot={{ r: 3 }} />
                      </ComposedChart></ResponsiveContainer>
                    </div>
                    <div className="card chart-card"><h3>Clients Won</h3><p className="cap">Wins (bars) with won value labelled &amp; cost per acquisition (line) by week</p>
                      <ResponsiveContainer width="100%" height={240}><ComposedChart data={W} margin={{ left: -4, right: 6, top: 16 }}>
                        <CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="label" fontSize={11} stroke="var(--muted)" /><YAxis yAxisId="l" fontSize={10} stroke="var(--muted)" tickFormatter={(v) => '$' + fmtCompact(v)} /><YAxis yAxisId="r" orientation="right" fontSize={10} stroke="var(--muted)" allowDecimals={false} /><Tooltip formatter={(v, nm) => (nm === 'Wins' ? fmtNumber(v) : fmtCurrency(v, currency))} /><Legend />
                        <Bar yAxisId="r" dataKey="won" name="Wins" fill="#c9c1ff" radius={[3, 3, 0, 0]} maxBarSize={42}>
                          <LabelList dataKey="won" position="insideTop" fill="var(--text)" fontSize={10} fontWeight={700} formatter={(v) => (v ? fmtNumber(v) : '')} />
                          <LabelList dataKey="wonValue" position="top" fill="var(--muted)" fontSize={9.5} formatter={(v) => (v ? '$' + fmtCompact(v) : '')} />
                        </Bar>
                        <Line yAxisId="l" type="monotone" dataKey="cpa" name="CPA" stroke="#6d5efc" strokeWidth={2.5} dot={{ r: 3 }} />
                        {Number(kpis.cpa) > 0 && <ReferenceLine yAxisId="l" y={Number(kpis.cpa)} stroke="var(--text)" strokeDasharray="5 4" label={{ value: `KPI ${money(kpis.cpa)}`, fontSize: 10, fill: 'var(--muted)', position: 'insideTopRight' }} />}
                      </ComposedChart></ResponsiveContainer>
                    </div>
                    <div className="card chart-card"><h3>Funnel</h3><p className="cap">Leads → Appt's → Shown → Won by week</p>
                      <ResponsiveContainer width="100%" height={240}><BarChart data={W} margin={{ left: -6, right: 6, top: 14 }}>
                        <CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="label" fontSize={11} stroke="var(--muted)" /><YAxis fontSize={10} stroke="var(--muted)" allowDecimals={false} /><Tooltip /><Legend />
                        <Bar dataKey="leads" name="Leads" fill="#f5a524" radius={[3, 3, 0, 0]} maxBarSize={20}><LabelList dataKey="leads" position="top" fill="var(--muted)" fontSize={9.5} formatter={(v) => (v ? fmtNumber(v) : '')} /></Bar>
                        <Bar dataKey="booked" name="Appt's" fill="#b0325f" radius={[3, 3, 0, 0]} maxBarSize={20}><LabelList dataKey="booked" position="top" fill="var(--muted)" fontSize={9.5} formatter={(v) => (v ? fmtNumber(v) : '')} /></Bar>
                        <Bar dataKey="shown" name="Shown" fill="#2f8f83" radius={[3, 3, 0, 0]} maxBarSize={20}><LabelList dataKey="shown" position="top" fill="var(--muted)" fontSize={9.5} formatter={(v) => (v ? fmtNumber(v) : '')} /></Bar>
                        <Bar dataKey="won" name="Won" fill="#6d5efc" radius={[3, 3, 0, 0]} maxBarSize={20}><LabelList dataKey="won" position="top" fill="var(--muted)" fontSize={9.5} formatter={(v) => (v ? fmtNumber(v) : '')} /></Bar>
                      </BarChart></ResponsiveContainer>
                    </div>
                    {(wk.data.lostReasons || []).length > 0 && <div className="card chart-card"><h3>Lost reasons</h3><p className="cap">Why deals were lost · {rangeLbl}</p>
                      <ResponsiveContainer width="100%" height={240}><PieChart><Pie data={wk.data.lostReasons.slice(0, 8)} dataKey="count" nameKey="name" innerRadius={54} outerRadius={86} paddingAngle={2} stroke="none">{wk.data.lostReasons.slice(0, 8).map((x, i) => <Cell key={i} fill={acolor(i)} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer>
                      <div className="legend" style={{ flexWrap: 'wrap', fontSize: 11 }}>{wk.data.lostReasons.slice(0, 8).map((x, i) => <span key={i}><i className="swatch" style={{ background: acolor(i) }} /> {x.name} {x.count}</span>)}</div>
                    </div>}
                  </>}
                </div>
                <Caveat>Weeks run Monday-Sunday (ISO week number shown). Leads = Meta leads + Google conversions. Appointments / shown / won come from Caalano Systems pipeline stages (opportunities created that week). KPI lines &amp; vs-KPI deltas use the weekly targets you set per client in Settings.</Caveat>
              </>
            )
          })()}
    </>
  )
}

