  const prevRange = prevRangeOf(range)
  const prevCcDrill = useCcDrill(clientId, prevRange || range, nx('drill'), chan, wonBasis)
  // Refresh: queue the warm rebuild of this tab's views, then poll for a minute.
  useEffect(() => {
    if ((!nonce && !refreshTick) || isViewer || !clientId || !range || !range.from) return
    let alive = true
    const strip = (u) => (u ? u.replace(/^\/\.netlify\/functions\/windsor\?/, '') : null)
    const views = [
      `client=${clientId}&scope=health&${rangeQuery(range)}&wonBasis=${wonBasis}`,
      strip(ccDrillUrl(clientId, range, 0, chan, wonBasis)),
      prevRange ? strip(ccDrillUrl(clientId, prevRange, 0, chan, wonBasis)) : null,
      strip(crmAggUrl(clientId, range, 0, chan)),
      strip(spendDailyUrl(clientId, range, 0)),
      `scope=forms&client=${clientId}&${rangeQuery(range)}`,
      rangeDays > 0 && rangeDays <= 31 ? `scope=usercalls&client=${clientId}&${rangeQuery(range)}&callsonly=1` : null,
    ].filter(Boolean)
    setRefreshing(true)
    fetch(`/.netlify/functions/windsor?scope=revalidate&client=${clientId}&${views.map((v) => `u=${encodeURIComponent(v)}`).join('&')}`).catch(() => {})
    let n = 0
    const t = setInterval(() => { if (!alive) return; n++; setPoll((p) => p + 1); if (n >= 6) { clearInterval(t); setRefreshing(false) } }, 10000)
    return () => { alive = false; clearInterval(t); setRefreshing(false) }
  }, [nonce, refreshTick])
  const pccRaw = (prevRange && prevCcDrill.status === 'ok' && prevCcDrill.data && prevCcDrill.data.oppsBySource) ? prevCcDrill.data : null
  const pcc = useMemo(() => lensCc(pccRaw, pipe), [pccRaw, pipe])
  const money = (v) => fmtCurrency(v, currency)
  // The intelligence model: reach with the bottleneck, channels to outcomes,
  // movers, indexing. Same (lensed, channel-scoped) payloads as every tile.
  const keTick = JSON.stringify(loadKeyEvents(clientId))
  const intelExtra = useMemo(() => {
    const forms = (formsFeed.data && formsFeed.data.forms) || []
    const locMap = new Map()
    for (const f of forms) for (const l of (f.locations || [])) { const k = l.label || l.value || l.name; if (!k) continue; const e = locMap.get(k) || { label: k, leads: 0, booked: 0, won: 0, lost: 0 }; e.leads += l.leads || 0; e.booked += l.booked || 0; e.won += l.won || 0; e.lost += l.lost || 0; locMap.set(k, e) }
    const calls = callsFeed.data && !callsFeed.data.error && Array.isArray(callsFeed.data.byUser) ? callsFeed.data.byUser : []
    return { wide: true, reps: (crmAgg && crmAgg.reps) || [], calendars: (cc && cc.bookingByCalendar) || [], locations: [...locMap.values()], forms, calls }
  }, [formsFeed.data, crmAgg, cc, callsFeed.data])
  const intel = useMemo(() => buildIntel(cc, pcc, clientId, money, intelExtra), [cc, pcc, clientId, keTick, cashOn, intelExtra]) // eslint-disable-line
  // Spend for the active channel toggle, from a (lensed) drill payload.
  const spendOf = (d, chn) => { const sp = (d && d.spend) || {}; return chn === 'meta' ? (sp.meta || 0) : chn === 'google' ? (sp.google || 0) : chn === 'nonpaid' ? 0 : (sp.total || 0) }
  const [drill, setDrill] = useState(null)
  // V2: secondary table columns shown on demand; sections wrap as collapsible.
  const [moreCols, setMoreCols] = useState(false)
