  const prevRangeW = prevRangeOf(range)
  const ccPrevW = useCcDrill(crmId && prevRangeW ? crmId : null, prevRangeW || range, nonce, 'all', wonBasis)
  const keTickW = JSON.stringify(loadKeyEvents(client.id))
